INSERT INTO public.cache_semantico
  (hash_prompt, prompt_original, prompt_normalizado, resposta_cacheada, tokens_input, tokens_output, fonte_original, qualidade_score, criado_por, hits)
VALUES
('8c32f0258178518c56e8eb8892d7787e66e354616dab630b7279798dd366af01', 'SWOT Nubank', 'swot nubank', '{"texto": "### Forças\n1. **Marca forte** - 95M clientes, top of mind...\n### Fraquezas\n1. **Dependência CDI** - 80% receita...\n### Oportunidades\n1. **BaaS** - vender infra pra outros bancos...\n### Ameaças\n1. **Regulação BC** - open finance reduz switching cost..."}'::jsonb, 120, 850, 'LLAMA', 0.75, 'system', 0),
('a4bd2e98c67a3942061540874366ac235f1c81af855d502a02ba6ff4c4cd7646', 'SWOT Inter', 'swot inter', '{"texto": "### Forças\n1. **Super App** - bank + shopping + invest...\n### Fraquezas\n1. **CAC alto** - R$ 120 vs Nubank R$ 30..."}'::jsonb, 118, 820, 'LLAMA', 0.75, 'system', 0),
('a89bbacc84f971739b7d17e8682156983b86234aa984ae7b5178834811eb9ef8', 'SWOT Magazine Luiza', 'swot magazine luiza', '{"texto": "### Forças\n1. **MagaluPay** - 20M contas digitais...\n### Ameaças\n1. **Amazon** - logística imbatível..."}'::jsonb, 125, 880, 'LLAMA', 0.75, 'system', 0),
('23847e3b123c104122ee3f77565c8338fe01a5258238ef41a5b043bf473a9b95', '5 forcas porter uber', '5 forcas porter uber', '{"texto": "1. **Rivalidade**: Alta - 99, Cabify...\n2. **Entrantes**: Média - barreira regulatória...\n3. **Fornecedores**: Motoristas têm poder...\n4. **Clientes**: Alto poder - trocam por R$1...\n5. **Substitutos**: Transporte público, bike..."}'::jsonb, 130, 900, 'LLAMA', 0.75, 'system', 0),
('0426ab415767a881f0f27ad4485b0733c238b8e0abab09e5536fe926a8f08320', 'analise pestel brasil 2024', 'analise pestel brasil 2024', '{"texto": "Político: Reforma tributária...\nEconômico: Selic 10.5%...\nSocial: Classe C digitalizada...\nTecnológico: Pix 150M usuários...\nAmbiental: ESG obrigatório...\nLegal: LGPD multas R$ 50M..."}'::jsonb, 140, 950, 'LLAMA', 0.75, 'system', 0),
('0711ca828c0dae94e0d9fd5c38c4e0bf93f287e8055de601003a62a8c0f6f02b', 'business model canvas ifood', 'business model canvas ifood', '{"texto": "Parceiros: Restaurantes, entregadores...\nAtividades: Algoritmo roteamento...\nRecursos: App 60M downloads...\nProposta: Entrega 30min...\nRelacionamento: Suporte chat...\nCanais: App iOS/Android...\nSegmentos: PF faminto, PJ eventos...\nCustos: Incentivo entregador...\nReceitas: Taxa 27% restaurante..."}'::jsonb, 150, 1000, 'LLAMA', 0.75, 'system', 0),
('2dce22f7a67359b9a4ef1504547b6d3178090992fad584313831c2537c12a74c', 'Como sair das dívidas método bola de neve', 'como sair das dividas metodo bola de neve', '{"texto": "1. **Liste todas dívidas** menor pra maior, ignore juros.\n2. **Pague mínimo** em todas, exceto a menor.\n3. **Jogue todo extra** na menor dívida.\n4. **Quite a menor** e comemore - efeito psicológico.\n5. **Role o valor** da quitada pra próxima menor.\n6. **Repita** até zerar. Tempo médio: 24 meses pra R$ 15k."}'::jsonb, 80, 450, 'LLAMA', 0.75, 'system', 0),
('d702e9f62d6adfaacfa6b04e388283fadd2033d13ac9f8afb858b58e7b49bafd', 'Quanto devo guardar por mês regra 50-30-20', 'quanto devo guardar por mes regra 503020', '{"texto": "50% **Necessidades**: aluguel, conta, mercado.\n30% **Desejos**: lazer, delivery, assinatura.\n20% **Poupança**: reserva emergência + investimentos.\nEx: Salário R$ 3.000 = R$ 600/mês guardado. Em 1 ano = R$ 7.200."}'::jsonb, 75, 400, 'LLAMA', 0.75, 'system', 0),
('c16a328206269937040d4243b1b3ce996397a406f07dc80e8074c18526217be6', 'Diferença CDB LCI LCA qual melhor', 'diferenca cdb lci lca qual melhor', '{"texto": "CDB: Paga IR 15-22.5%. Rende 100% CDI.\nLCI/LCA: **Isento IR**. Rende 90-95% CDI.\nMelhor: LCI/LCA se prazo > 2 anos. CDB se liquidez diária.\nEx: R$ 10k em LCI 95% CDI por 2 anos = R$ 12.100 líquido. CDB daria R$ 11.700."}'::jsonb, 85, 480, 'LLAMA', 0.75, 'system', 0),
('4bef17872e7cfec4f70d0388de7bcaba92ab3789770bee343598c76f65257759', 'Como fazer declaração IR 2024 passo a passo', 'como fazer declaracao ir 2024 passo a passo', '{"texto": "1. **Baixe programa** Receita Federal.\n2. **Importe dados** empregador/informe bancos.\n3. **Declare dependentes** se tiver.\n4. **Lance gastos** saúde/educação sem limite.\n5. **Confira pendências** ícone amarelo.\n6. **Transmita** até 31/05. Multa: R$ 165 mínimo."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('11c0c7cf314f0e24cb62da03d152c655c1a8e911258fcdda672abf64cf8783be', 'Vale a pena financiar ou alugar imóvel', 'vale a pena financiar ou alugar imovel', '{"texto": "Financiar: Juros 10% a.a. Parcela R$ 3k em imóvel R$ 300k.\nAlugar: R$ 1.8k mesmo imóvel.\nDiferença R$ 1.2k/mês investida a 12% a.a = R$ 500k em 30 anos.\n**Regra**: Se aluguel < 0.5% valor imóvel, alugue e invista diferença."}'::jsonb, 95, 520, 'LLAMA', 0.75, 'system', 0),
('98a467c46f617fc7df341c0672ea0ec3d526b41c6ec18ef357fba9be5304f71e', 'Tesouro Direto Selic vs IPCA vs Prefixado', 'tesouro direto selic vs ipca vs prefixado', '{"texto": "Selic: Rende 100% taxa Selic. Melhor pra reserva emergência. Liquidez D+1.\nIPCA+: Rende IPCA + juros. Protege inflação. Melhor longo prazo >5 anos.\nPrefixado: Taxa fixa. Bom se Selic vai cair. Risco se Selic subir.\n**Estratégia**: 40% Selic, 60% IPCA+ longo prazo."}'::jsonb, 88, 490, 'LLAMA', 0.75, 'system', 0),
('acaa87697def84ef3ccbeab40c7b9b171b0bb585233bbccafabda335bc192871', 'Como investir 1000 reais iniciante', 'como investir 1000 reais iniciante', '{"texto": "1. **Reserva emergência**: R$ 500 Tesouro Selic. Liquidez diária.\n2. **CDB Banco médio**: R$ 300 110% CDI liquidez 90 dias.\n3. **ETF BOVA11**: R$ 200 bolsa brasileira.\nRisco baixo. Rende ~11% a.a. Em 5 anos: R$ 1.685.\nCorretora: NuInvest, Inter, XP - taxa zero."}'::jsonb, 82, 460, 'LLAMA', 0.75, 'system', 0),
('6ad6e7ad6aacbb033bb2319a1c29c1de6acba2e8a1e554b31cf5084ddf8bca72', 'Cartão de crédito vale a pena ou não', 'cartao de credito vale a pena ou nao', '{"texto": "Vale SE: 1. Paga fatura 100% sempre. 2. Usa cashback/milhas > anuidade. 3. Organiza gasto.\nNÃO vale SE: 1. Parcela fatura. Juros 15% a.m = 430% a.a. 2. Gasta mais por ter limite.\n**Regra**: Limite = 30% renda. Estoura = cancela."}'::jsonb, 86, 470, 'LLAMA', 0.75, 'system', 0),
('0d7af5b858c866c942536738fed571d1969abd9804000b4a30ec668b88d380ac', 'Como fazer reserva de emergência', 'como fazer reserva de emergencia', '{"texto": "Valor: 6x custo mensal. Gasto R$ 3k = reserva R$ 18k.\nOnde: Tesouro Selic ou CDB 100% CDI liquidez diária.\nNÃO: Poupança rende 6% a.a, inflação 5%. Perde dinheiro.\nPrazo: 12-18 meses guardando 20% salário. Começa com R$ 100."}'::jsonb, 84, 465, 'LLAMA', 0.75, 'system', 0),
('97ccae6eedacca045a3916f3dc9be149adb1d19da8982e3f897b1477ba0a1fb0', 'Financiamento veículo taxa boa quanto', 'financiamento veiculo taxa boa quanto', '{"texto": "Taxa boa: Até 1.5% a.m = 19.5% a.a.\nTaxa mercado: 2.5% a.m = 34% a.a.\nCarro R$ 50k, 48x: Taxa 1.5% = parcela R$ 1.480. Taxa 2.5% = R$ 1.780.\nDiferença: R$ 14.400 em juros.\n**Negocie**: Entrada 30% + score 800 = taxa menor."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('bdc4159b81ae8be2e67cb03fa20637e46c608b4f31b8ee072ea44344d246d8fb', 'Score Serasa como aumentar rápido', 'score serasa como aumentar rapido', '{"texto": "1. **Nome limpo**: Negocie dívida, pague à vista com desconto.\n2. **Cadastro Positivo**: Ative no Serasa. Pagar conta em dia sobe score.\n3. **Cartão crédito**: Use 30% limite e pague total.\n4. **Dados atualizados**: CPF, endereço, telefone.\n5. **Tempo**: 3-6 meses pra subir 100 pontos.\nScore 800+ = crédito fácil."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('6f6a267ab1d391962b6950161a7df1ff2b5a0b89f7695833b22a05f84e51dbf2', 'Consórcio vale a pena ou financiamento', 'consorcio vale a pena ou financiamento', '{"texto": "Consórcio: Sem juros, só taxa admin 15-20%. Contempla por sorteio/lance. Pode demorar 10 anos.\nFinanciamento: Juros 10% a.a. Pega bem na hora.\nCarro R$ 50k: Consórcio custo R$ 60k total. Financiamento R$ 75k.\n**Vale consórcio** se não tem pressa e disciplina. **Financiamento** se precisa agora."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('cb5588150045d9c8eb2937ae318e61c20bbb1c79a9e4a712d68ec7766f6583b1', 'Como calcular aposentadoria INSS valor', 'como calcular aposentadoria inss valor', '{"texto": "Regra nova: 60% média salários + 2% por ano acima 20 anos contribuição.\nMédia R$ 5k, 35 anos: 60% + 30% = 90% de R$ 5k = R$ 4.500.\nTeto 2024: R$ 7.786.\n**Simule**: meu.inss.gov.br. Paga mínimo 15 anos pra aposentar."}'::jsonb, 88, 485, 'LLAMA', 0.75, 'system', 0),
('4bf1beb48ef3ad22263c946d784a9225004d2a7670cfb35ec13b6e32cbbf95e0', 'Previdência privada PGBL ou VGBL', 'previdencia privada pgbl ou vgbl', '{"texto": "PGBL: Deduze até 12% renda no IR. Bom se declara completo e paga IR.\nVGBL: Não deduz. Bom se isento ou simples.\nTaxa admin: <1% a.a. >1.5% foge.\n**Regra**: Salário > R$ 5k + declara completo = PGBL. Senão VGBL."}'::jsonb, 87, 480, 'LLAMA', 0.75, 'system', 0),
('e7b44475c30cad2fa2db725fb05aa8b86d84011b9534b3cd738ea93aec83fd70', 'Como economizar no mercado 30%', 'como economizar no mercado 30', '{"texto": "1. **Lista pronta**: Vai 1x/semana, sem fome.\n2. **Marca própria**: 40% mais barato, mesma fábrica.\n3. **Atacarejo**: Assaí, Atacadão pra não perecível.\n4. **App cupom**: Clube Extra, Meu Carrefour.\n5. **Feira fim dia**: 50% desconto.\nEconomia R$ 3k/ano pra família 4 pessoas."}'::jsonb, 85, 475, 'LLAMA', 0.75, 'system', 0),
('a5f33348207517c8f8fd87789aa41962185715d8d60814836422f54108c51c8f', 'Seguro de vida vale a pena', 'seguro de vida vale a pena', '{"texto": "Vale SE: Tem dependente + dívida + sem reserva 12x salário.\nCobertura: 10x renda anual. R$ 5k/mês = R$ 600k.\nCusto: Homem 30 anos = R$ 50/mês.\nNÃO vale: Solteiro, sem filho, reserva ok.\n**Seguro prestamista**: Só se financiamento >5 anos."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('28b257e49da95d4cafe2302a6be493d97680e1311a2c2fc6be4241216e46bab7', 'Como renegociar dívida banco desconto', 'como renegociar divida banco desconto', '{"texto": "1. **Ligue cobrança**: Peça setor acordo, não atendente.\n2. **À vista**: Pede 70-90% desconto. R$ 10k vira R$ 2k.\n3. **Parcelado**: Pede tirar juros, só correção.\n4. **Procon**: Se negar, abre reclamação.\n5. **Feirão**: Serasa/Spc 2x ano, desconto 95%.\nPrazo prescreve: 5 anos, mas nome suja."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('1f63766b9eebd586bcff9ad8cdfa9e581d3f5be18df5047ea2ef596b8c86f07f', 'Imposto de renda sobre aluguel como pagar', 'imposto de renda sobre aluguel como pagar', '{"texto": "Aluguel > R$ 2.259/mês: Paga Carnê-Leão mensal.\nTabela: 7.5% a 27.5%.\nEx: R$ 3k aluguel = R$ 95 IR/mês.\n**Dedução**: IPTU, corretagem, taxa admin.\nDeclara na DIRPF ano seguinte. Multa: 50% imposto se não pagar."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('2b2b26217f258ed7246f1f20efc31f9e8b0496272e74a8f82765757a84e10ab8', 'Portabilidade financiamento imóvel como fazer', 'portabilidade financiamento imovel como fazer', '{"texto": "1. **Simule**: Novo banco taxa menor.\n2. **Peça carta**: Banco atual em 5 dias.\n3. **Proposta**: Novo banco quita dívida.\n4. **Custo**: ITBI 0.5%, registro R$ 3k. Compensa se economia > custo.\nEx: R$ 300k, reduz 1% a.a = economiza R$ 30k.\n**CET**: Compare custo total."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('6f87faf832f27e34e686bf3619f5a66cecfc91e6bdf900810f0f7f51f7ac8ed8', 'Bitcoin vale a pena investir quanto', 'bitcoin vale a pena investir quanto', '{"texto": "Volátil: Cai 80%, sobe 500%. Só invista dinheiro que pode perder.\nAlocação: 1-5% patrimônio. R$ 100k = R$ 1-5k BTC.\nOnde: Mercado Bitcoin, Binance, Foxbit.\nSegurança: Hardwallet Ledger.\nImposto: Venda >R$ 35k/mês paga 15% lucro.\n**Regra**: Não é reserva, é aposta."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('cc1de1b28b08143a1624c0a136f2d6f25dd9171ebad1f6d43c62888a6b5146c6', 'Como pedir aumento salário script pronto', 'como pedir aumento salario script pronto', '{"texto": "Agende reunião. Script: `Chefe, nos últimos 6 meses entreguei X, Y, Z. Gerou R$ 50k pra empresa. Pesquisei mercado: cargo paga R$ 8k, recebo R$ 6k. Gostaria de revisar pra R$ 7.5k. O que acha?` Se negar: `O que preciso entregar pra chegar lá em 3 meses?` Documente tudo."}'::jsonb, 88, 460, 'LLAMA', 0.75, 'system', 0),
('8805fd247fde6a793781b1b2435f7314f27730bf84b5b8c3cd79072c73105802', 'CLT vs PJ qual paga menos imposto', 'clt vs pj qual paga menos imposto', '{"texto": "CLT R$ 10k: Líquido R$ 7.200. Empresa paga R$ 13.500 total.\nPJ R$ 10k: Simples Anexo III 6%. Líquido R$ 9.400. Paga INSS R$ 1.400.\n**PJ ganha** se renda > R$ 5k e sem benefícios CLT. Atenção: pejotização ilegal se só 1 cliente, sem autonomia."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('15222435e2993956dd076a520786c0c1b639d85437e29495f120c3480056beea', 'Como fazer LinkedIn que atrai recrutador', 'como fazer linkedin que atrai recrutador', '{"texto": "1. **Foto**: Profissional, sorriso, fundo neutro.\n2. **Headline**: Cargo + resultado. Ex: `Dev Python | Automatizei R$ 1M/ano`.\n3. **Sobre**: 3 linhas dor + solução + CTA.\n4. **Experiência**: Bullet com número. `Aumentei vendas 30%`.\n5. **Atividade**: Posta 2x/semana caso técnico.\n6. **Open to Work**: Ativa sem foto se empregado."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('c0543abbe292ae1bcf1600480e256a87d2cd34b12325ed1db463fae15aa8b4cc', 'Perguntas entrevista emprego como responder', 'perguntas entrevista emprego como responder', '{"texto": "**Fale sobre você**: 60s. Presente-Passado-Futuro. `Sou X, fiz Y, busco Z nessa vaga`.\n**Defeito**: 1 real + o que faz pra melhorar. `Ansioso, uso Pomodoro`.\n**Por que sair**: Nunca falar mal. `Busco desafio X que aqui não tem`.\n**Salário**: `Pesquisei R$ 8-10k. Aberto negociar`."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('4bbea9a3cf4e9845c9e6aecb80bf44f5e4b2c8de72b5708a1d389f561921dba5', 'Como calcular hora trabalhada freelancer', 'como calcular hora trabalhada freelancer', '{"texto": "Salário CLT desejado / 160h = valor base. R$ 8k / 160 = R$ 50/h.\nAdiciona: 30% impostos + 20% férias/13º + 20% risco = 70%.\nR$ 50 * 1.7 = **R$ 85/hora**.\nMínimo: Nunca menos R$ 50/h se pleno.\nProjeto 40h = R$ 3.400."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('1005a89df11916a8dc981e5b38664311ee5e9e61863777379b535b6ab1f44109', 'Burnout sinais e como sair', 'burnout sinais e como sair', '{"texto": "Sinais: Exaustão, cinismo, ineficácia. Dorme mal, irritado, procrastina.\nSair: 1. **Férias 14 dias** sem celular. 2. **Terapia**: Psicólogo TCC. 3. **Limite**: 8h/dia, sem fds. 4. **Médico**: Atestado se grave. 5. **Troca emprego** se cultura tóxica.\nINSS paga auxílio-doença se >15 dias."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('cb401318c6f936736e891ec3096db3bd546177a046871c69c20d5ffb3861b1f8', 'Como fazer transição de carreira aos 40', 'como fazer transicao de carreira aos 40', '{"texto": "1. **Teste**: Curso barato área nova 40h. Gostou?\n2. **Dinheiro**: Reserva 12 meses custo. Salário vai cair.\n3. **Rede**: LinkedIn, evento, café com quem já faz.\n4. **Ponte**: Freelance fds antes pedir demissão.\n5. **Prazo**: 18 meses transição completa.\nÁreas: Dados, produto, marketing aceitam 40+."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('761998164f47d35936cc2c8586c673ad268b05aa0313665889b0316f67ad117f', 'Demissão como negociar melhor acordo', 'demissao como negociar melhor acordo', '{"texto": "CLT: Aviso prévio indenizado 30 dias + multa 40% FGTS + férias + 13º.\n**Negocia**: 1. Data saída pós PLR. 2. PLR proporcional. 3. Plano saúde 6 meses. 4. Carta recomendação.\nPDV: Pode pedir 6-12 salários extra.\n**Não assine** nada sem ler. Advogado se >R$ 50k."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('d80378c70655d75a184dbd8a45ed2128056c81f6d3f84dc77fc6f8ef21c3bd2d', 'Inglês para trabalho quanto tempo fluente', 'ingles para trabalho quanto tempo fluente', '{"texto": "Zero ao B2: 600h estudo. 1h/dia = 20 meses.\nAcelera: 1. **Imersão**: Série legenda inglês, muda celular. 2. **Cambly**: 3x/semana 30min R$ 300/mês. 3. **Anki**: 20 palavra/dia.\nEntrevista: Treina 50 perguntas comuns.\n**Certificado**: TOEFL 90+ ou IELTS 7.0."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('a4e3e6fe4d3b1401a3e5ce88a23b5dd8872fb56afabcdbf27f9bf8088dbaa0ca', 'Como virar líder sem cargo chefia', 'como virar lider sem cargo chefia', '{"texto": "1. **Entrega**: Puxa tarefa ninguém quer, entrega antes.\n2. **Ensina**: Documenta, faz tutorial pro time.\n3. **Resolve**: Leva problema + 2 soluções pro chefe.\n4. **Rede**: Almoça com outras áreas.\n5. **Visibilidade**: Apresenta resultado reunião.\n6 meses virando referência, cargo vem."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('790578af6116fae9acde7a1204562bb271f5c114032e20d496f709b0c906550b', 'Home office como ser produtivo', 'home office como ser produtivo', '{"texto": "1. **Espaço**: Mesa só trabalho, não sofá.\n2. **Rotina**: Acorda, banho, roupa. Horário fixo.\n3. **Pomodoro**: 25min foco, 5min pausa. 4 ciclos = pausa longa.\n4. **Async**: Slack status, não reunião pra tudo.\n5. **Limite**: Fecha notebook 18h. Evita burnout.\nEmpresa economiza R$ 1k/mês por funcionário."}'::jsonb, 88, 490, 'LLAMA', 0.75, 'system', 0),
('46e2ecca830efc2422d4a6247ac55e0914b37745893578fa98af14294671c68a', 'Feedback negativo como dar sem briga', 'feedback negativo como dar sem briga', '{"texto": "Método SBI: **Situação** + **Comportamento** + **Impacto**.\n`Ontem na reunião [S], você interrompeu 3x [C], time não falou [I]. Pode esperar pessoa terminar?`\nNunca: `Você é grosso`. Sempre: comportamento específico.\nElogio público, crítica privada."}'::jsonb, 87, 485, 'LLAMA', 0.75, 'system', 0),
('75ca07c83f03bf4cbd4c28baeb7b3177181e32bc12fa3c28a80d3ba29659e25d', 'Como pedir demissão sem queimar ponte', 'como pedir demissao sem queimar ponte', '{"texto": "1. **Aviso**: 30 dias, carta escrita. `Agradeço oportunidade, decidi novo desafio`.\n2. **Transição**: Documenta tudo, treina substituto.\n3. **Saída**: Entrega projeto, devolve equipamento.\n4. **LinkedIn**: Posta agradecendo, não critica.\n5. **Contato**: Mantém ex-chefe no WhatsApp.\nMercado é pequeno, vocês se esbarram."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('e18d6256c7057cf6408c2840e4bdf35d8b461d2c04118598121db9e2f4a24770', 'Certificação que dá emprego rápido TI', 'certificacao que da emprego rapido ti', '{"texto": "Cloud: **AWS Cloud Practitioner** 40h estudo, R$ 300 prova. Salário R$ 6k júnior.\nDados: **Google Data Analytics** Coursera R$ 200/mês. R$ 5k.\nSegurança: **CompTIA Security+** R$ 1.500. R$ 8k.\nDev: Não precisa cert, precisa GitHub.\n**ROI**: 3 meses salário paga curso."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('c86141c47c9eb5ab2483828e4d3109e880c3511aabc7226fbd26b9a591d9f09f', 'Plano de carreira 5 anos como fazer', 'plano de carreira 5 anos como fazer', '{"texto": "Ano 1: Júnior→Pleno. Certificação + 1 projeto grande.\nAno 2: Pleno→Sênior. Lidera 2 pessoas.\nAno 3: Tech Lead. Salário R$ 15k.\nAno 4: Gerente ou Staff Engineer. R$ 20k.\nAno 5: Head/Diretor. R$ 30k+.\nRevisa 6/6 meses. Se empresa não promove, troca."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('6f98b3698be0e3f929643a05332d2d6928351a93522f94cee483458164a18313', 'Como abrir MEI passo a passo 2024', 'como abrir mei passo a passo 2024', '{"texto": "1. **Portal Gov.br**: gov.br/mei\n2. **CNPJ na hora**: grátis, sem contador.\n3. **DAS**: R$ 71/mês, paga dia 20.\n4. **Limite**: R$ 81k/ano faturamento.\n5. **Atividades**: 1 principal + 15 secundárias.\n6. **NFE**: Emita no portal prefeitura.\nObs: Não pode ter sócio nem funcionário CLT."}'::jsonb, 100, 550, 'LLAMA', 0.75, 'system', 0),
('6eddbdc22e7dc0d6b7ba7a8037105a45cb9206c67f37fe04a8e219ed586de678', 'MEI vs ME vs EPP diferenças', 'mei vs me vs epp diferencas', '{"texto": "MEI: Fatura até R$ 81k/ano. DAS R$ 71. 1 funcionário.\nME: Até R$ 360k/ano. Simples 4-19.5%. Sem limite funcionário.\nEPP: R$ 360k a R$ 4.8M/ano. Simples 4-19.5%.\n**Pula pro ME** se passar R$ 6.750/mês médio."}'::jsonb, 95, 530, 'LLAMA', 0.75, 'system', 0),
('3d12ec87c08cb1a02cdcd2b3c725b4278823028f20d024bae525610610d30bbf', 'Simples Nacional Anexo III vs V qual usar', 'simples nacional anexo iii vs v qual usar', '{"texto": "Anexo III: 6% a 33%. Serviços intelectuais: dev, advogado, médico.\nAnexo V: 15.5% a 30.5%. Serviços em geral: limpeza, obra.\n**Fator R**: Se folha > 28% faturamento, cai pro Anexo III. Ex: Dev R$ 20k, pró-labore R$ 6k = 30% = Anexo III 6%."}'::jsonb, 105, 580, 'LLAMA', 0.75, 'system', 0),
('31ba8f4361aed6e940389018466ab505f6e00f44cbc2a116ab176c42a6ba9a13', 'Como emitir nota fiscal MEI prefeitura SP', 'como emitir nota fiscal mei prefeitura sp', '{"texto": "1. **Acesse**: nfe.prefeitura.sp.gov.br\n2. **Login**: Certificado ou senha web.\n3. **Nova NFS-e**: Tomador CNPJ/CPF, serviço, valor.\n4. **CNAE**: Use o do seu MEI.\n5. **ISS**: MEI isento SP.\n6. **Envie**: PDF pro cliente. Guarde 5 anos."}'::jsonb, 98, 540, 'LLAMA', 0.75, 'system', 0),
('006946a830fd975abc2cec3c69d26b75731f6b47160cfeea02b13ab0c2db0a92', 'Pró-labore quanto tirar para pagar menos imposto', 'prolabore quanto tirar para pagar menos imposto', '{"texto": "Regra: **28% do faturamento** pra cair Anexo III Simples.\nFatura R$ 20k: Pró-labore R$ 5.600.\nINSS: 11% sobre R$ 5.600 = R$ 616.\nIR: Isento até R$ 2.259.\n**Total imposto**: 6% DAS + 11% INSS = 17% vs 27.5% CLT."}'::jsonb, 102, 560, 'LLAMA', 0.75, 'system', 0),
('ccae5c45f8325127cd0000d321265307041074721110debe97cdf8a709c5891c', 'DAS MEI atrasado como regularizar', 'das mei atrasado como regularizar', '{"texto": "1. **Portal PGMEI**: Gera DAS atrasado com multa 0.33%/dia + juros Selic.\n2. **Parcelamento**: Até 60x no portal Regularize.\n3. **CNPJ suspenso**: Se 2 anos sem pagar, cancela.\n4. **Prazo**: Regulariza antes inscrição dívida ativa.\nMulta máxima: 20%. Paga logo."}'::jsonb, 88, 490, 'LLAMA', 0.75, 'system', 0),
('44b7a17035c6b5f8694acd24720dafe1607c2ca09ddf37115794add5c4d9b59a', 'Capital social empresa quanto colocar', 'capital social empresa quanto colocar', '{"texto": "MEI: Não precisa.\nLTDA: Mínimo R$ 1. Regra: 10% faturamento anual previsto.\nFatura R$ 200k/ano = capital R$ 20k.\n**Risco**: Sócio responde até valor capital se dívida.\nPode integralizar em dinheiro ou bem. Prazo 5 anos."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('961cab79759c522bcaa0747a077cbc712a330b2ecae17ff45575b214b543be89', 'Contador MEI precisa ou não', 'contador mei precisa ou nao', '{"texto": "MEI: **Não precisa**. DAS e declaração anual faz sozinho.\nME/EPP: **Precisa**. Balancete, folha, SPED.\nCusto: R$ 300-800/mês.\n**Online**: Contabilizei, Conube R$ 99/mês.\nFoge se: Contador cobra % faturamento."}'::jsonb, 86, 480, 'LLAMA', 0.75, 'system', 0),
('52eaa03db0883e864db0d666cfc2aa805b894cee3b76e36299921ba0925667b2', 'Como contratar primeiro funcionário CLT custo', 'como contratar primeiro funcionario clt custo', '{"texto": "Salário R$ 2k: Custo total R$ 3.400/mês.\nInclui: FGTS 8%, INSS 20%, férias, 13º, VT, VR.\n**MEI**: Só 1 funcionário, salário mínimo.\n**Alternativa**: PJ R$ 2.5k sem vínculo. Risco processo.\nSimule: calc.empregador.com.br."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('98d44f2b2d68c468d00e4f2ec5fad559c70edfded937f1b541e45c0cb0d3a431', 'Certificado digital e-CNPJ qual comprar', 'certificado digital ecnpj qual comprar', '{"texto": "A1: Arquivo, R$ 200/ano. Instala PC. Vence 1 ano.\nA3: Token/cartão, R$ 300/3 anos. Mais seguro.\n**Onde**: Serasa, Valid, Certisign.\n**Uso**: Nota fiscal, eSocial, Receita.\nMEI não precisa. ME/EPP obrigatório."}'::jsonb, 87, 485, 'LLAMA', 0.75, 'system', 0),
('75b717af840703326352527f669ab0a485847f51e6a8d83649994a83ec8317fd', 'Fluxo de caixa simples planilha', 'fluxo de caixa simples planilha', '{"texto": "Colunas: Data | Entrada | Saída | Descrição | Saldo.\n1. **Saldo inicial**: Conta PJ dia 1.\n2. **Entradas**: Cliente pagou, soma.\n3. **Saídas**: DAS, aluguel, pró-labore, subtrai.\n4. **Saldo**: = anterior + entrada - saída.\n**Regra**: Saldo nunca negativo. Projeta 90 dias."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('adba7b0f5ad26092f8ca2313f3f05d2054e966fb37b50b6c155efa8d0ea04d3e', 'Precificação serviço como calcular', 'precificacao servico como calcular', '{"texto": "Custo hora: (Salário desejado + custos) / 160h.\nR$ 8k + R$ 2k custo = R$ 10k / 160 = R$ 62/h.\nMargem: 70% pra imposto+lucro.\nR$ 62 / 0.3 = **R$ 206/hora**.\nProjeto 40h = R$ 8.240.\nNunca cobra menos que CLT/hora."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('a20f738af2732bfdec1f1e48450129712b6ed42e767295ba12475f093def79d9', 'Como fechar empresa MEI inativa', 'como fechar empresa mei inativa', '{"texto": "1. **Baxa DAS**: Paga tudo atrasado no PGMEI.\n2. **Declaração**: Entrega DASN-SIMEI ano.\n3. **Portal**: gov.br/mei > Baixa.\n4. **Prazo**: 30 dias.\n5. **Custo**: Grátis.\nSe não baixar: CNPJ cancelado 2 anos, mas dívida continua CPF."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('809551ada69bf393abde3c857f44c1cf4a3b54d53ed8b20452e30b51254161f1', 'Inscrição estadual MEI precisa', 'inscricao estadual mei precisa', '{"texto": "MEI Comércio/Indústria: **Precisa** IE pra emitir NF-e produto.\nMEI Serviço: Não precisa, só inscrição municipal.\n**Como**: Portal Sefaz estado, grátis.\nSP: REDESIM, 3 dias.\nSem IE: Multa R$ 1k se vender produto."}'::jsonb, 88, 490, 'LLAMA', 0.75, 'system', 0),
('d22025b9ed7bf5e9f3459d3d775880da129624f6402cc563e19c160647470809', 'Conta PJ qual banco melhor taxa', 'conta pj qual banco melhor taxa', '{"texto": "C6 Bank: Zero tarifa, TED grátis, cartão múltiplo.\nInter: Zero, Pix grátis, investe automático.\nNubank PJ: R$ 0, boleto grátis.\nItaú: R$ 89/mês, mas gerente.\n**MEI**: C6 ou Inter. **Faturamento >50k**: Itaú relacionamento."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('aed7697735837df591ad8a6a4c95fde5f0297bd4b9fd915601cd9e7cf9381c47', 'Alvará funcionamento MEI precisa', 'alvara funcionamento mei precisa', '{"texto": "MEI: **Dispensado** alvará baixo risco Lei 13.874/19.\nAtividade risco: Consultório, oficina, precisa.\n**Consulta**: Portal prefeitura > Consulta prévia.\nSe precisar: Bombeiro + Vigilância. Custo R$ 500-2k.\nHome office: Maioria dispensada."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('4daf6d4b10941ee7992db719c2087eeeda62aea515c9f030d9a7cda5cfd1ddcc', 'eSocial para MEI como enviar', 'esocial para mei como enviar', '{"texto": "MEI sem funcionário: **Não envia**.\nMEI 1 funcionário: Envia S-1000, S-2200, S-1200.\n**Prazo**: Dia 7 mês seguinte.\n**Como**: Portal eSocial ou certificado.\nMulta: R$ 500 por evento atraso.\nContador faz R$ 100/mês."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('14dd9e1773a88ec125c14074de22bb0a694c709c1feb5c246291da57aa5c7003', 'Distribuição lucro MEI paga imposto', 'distribuicao lucro mei paga imposto', '{"texto": "MEI: **Isento IR** distribuição lucro.\nFatura R$ 5k, DAS R$ 71, sobra R$ 4.929 = lucro isento.\n**Não confunde**: Pró-labore paga INSS. Lucro não.\nME/EPP: Isento até 8% faturamento presumido.\nAcima: 15% IR. Contador calcula."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('fb3f456c3c239cee1226aa834cff87f5810476abf0152615904e985b1448db14', 'Máquina cartão melhor taxa MEI', 'maquina cartao melhor taxa mei', '{"texto": "Ton: Débito 1.99%, crédito 4.99%, recebe D+1. Sem aluguel.\nInfinitePay: Débito 1.49%, crédito 3.99%, D+1.\nSumUp: Débito 1.90%, crédito 4.60%, D+30.\n**MEI**: Ton ou InfinitePay. Vende R$ 10k/mês = economia R$ 50 vs banco.\nPix: Taxa zero todas."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('2c8e1e1f73c5e0eda6afd4dcaed1103e7d053b16b4d88901d322c39a4cf9f7e5', 'Protocolo manhã 5 hábitos energia dia todo', 'protocolo manha 5 habitos energia dia todo', '{"texto": "Heurística: Energia = Hidratação + Luz + Movimento + Frio + Proteína.\n1. **Água 500ml** ao acordar: repõe 8h desidratação. Cortisol cai 20%.\n2. **Sol 10min** sem óculos: zera melatonina, regula relógio biológico.\n3. **Agachamento 20x**: ativa maior músculo, glicose vira energia.\n4. **Banho frio 30s** final: noradrenalina +300%, foco 2h.\n5. **30g proteína** 1h após acordar: ovos+whey. Evita pico insulina.\nTempo total: 15min. ROI: +40% disposição comprovado."}'::jsonb, 90, 520, 'LLAMA', 0.75, 'system', 0),
('f5237608f0b6dc800ba46acd4678e2ce148dcaa4c87561d6a9e3bc2773ba8e5b', 'Como dormir melhor higiene do sono regra 10-3-2-1-0', 'como dormir melhor higiene do sono regra 103210', '{"texto": "Heurística 10-3-2-1-0:\n**10h antes**: Sem cafeína. Café 14h = meia-vida 22h.\n**3h antes**: Sem comida/peso. Digestão rouba 25% energia reparo.\n**2h antes**: Sem trabalho. Cortisol alto bloqueia melatonina.\n**1h antes**: Sem tela. Luz azul reduz melatonina 50%.\n**0**: Vezes que aperta soneca. Levanta direto.\nResultado: Adormece 15min, sono profundo +30%."}'::jsonb, 95, 540, 'LLAMA', 0.75, 'system', 0),
('9b531ed564fb8a15f85cb45efe1e46f0d3022c102855c4f21ab948a24f33cd2a', 'Treino 15min casa sem equipamento queima gordura', 'treino 15min casa sem equipamento queima gordura', '{"texto": "Heurística HIIT: Intensidade > duração.\nCircuito 4 rounds, 40s on 20s off:\n1. **Burpee**: Corpo todo, 15 cal/min.\n2. **Agachamento salto**: Quadríceps, pós-queima 24h.\n3. **Flexão**: Peito, core junto.\n4. **Prancha escalador**: Abdômen + cardio.\n5. **Descanso 60s** entre rounds.\nTotal: 15min = 200 cal + EPOC 14h. 3x/semana perde 2kg/mês."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('545800df155e2eef1e5ad6990734643ce7c346d32cb18264b0ff8052ffa3a871', 'Dieta anti-inflamatória lista supermercado', 'dieta antiinflamatoria lista supermercado', '{"texto": "Heurística: Inflamação = Açúcar + Óleo vegetal + Processado.\n**Compra**: Peixe gordo 2x/semana ômega3. Frutas vermelhas antioxidante. Brócolis sulforafano. Azeite extra virgem. Cúrcuma + pimenta preta.\n**Corta**: Açúcar, trigo, óleo soja, refrigerante, embutido.\n**Regra 80/20**: 80% comida real, 20% livre. Inflamação cai 60% em 30 dias."}'::jsonb, 94, 525, 'LLAMA', 0.75, 'system', 0),
('8793f47e47a45b874ad85140bf1b20b080f449205be8cdc16238928da83564d9', 'Jejum intermitente 16/8 como fazer seguro', 'jejum intermitente 168 como fazer seguro', '{"texto": "Heurística: Janela comer < janela reparar.\n16/8: Janta 20h, almoça 12h. 16h jejum.\n**Pode**: Água, café preto, chá sem açúcar. Mantém autofagia.\n**Quebra**: Proteína 30g almoço. Evita perder músculo.\n**Não fazer**: Grávida, diabético tipo1, distúrbio alimentar.\nBenefício: Insulina -30%, foco + hormônio crescimento 200%."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('36629f665161bd1b77e2068b149ad0469c5ca2a9b0e7d3b584d5235910c760ce', 'Postura trabalho casa corrige dor costas', 'postura trabalho casa corrige dor costas', '{"texto": "Heurística 90-90-90: Joelhos, quadril, cotovelo 90 graus.\n1. **Monitor**: Topo na altura olho. Pescoço neutro.\n2. **Teclado**: Cotovelo colado corpo. Evita tendinite.\n3. **Pés**: Chapados chão ou apoio.\n4. **Regra 20-20-20**: Cada 20min, olha 20m longe, 20s. Evita vista cansada.\n5. **Alongamento**: Gato-vaca 2min cada 2h.\nDor some 80% em 7 dias."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('a8e055bb2c311120dac47bcd37d5ffeb3055bebb4158d5a6f324e78cb2e61790', 'Respiração 4-7-8 ansiedade insônia', 'respiracao 478 ansiedade insonia', '{"texto": "Heurística: Expiração longa ativa parassimpático.\n1. **Inspira nariz 4s**: Enche 80% pulmão.\n2. **Segura 7s**: CO2 sobe, vaso dilata.\n3. **Sopra boca 8s**: Esvazia total, vagus nerve liga.\n4. **Repete 4x**: FC cai 15bpm, cortisol -25%.\nAntes dormir: Adormece 60% mais rápido. Crise: Para pânico 2min."}'::jsonb, 88, 495, 'LLAMA', 0.75, 'system', 0),
('51973fc6730029c557fc3b2f8959be6364f410dc700231baa95029e87d05e175', 'Água quanto beber fórmula peso', 'agua quanto beber formula peso', '{"texto": "Heurística: 35ml por kg peso.\n70kg = 2.45L/dia.\nAjusta: +500ml por hora exercício. +500ml calor >30C.\n**Cor xixi**: Amarelo claro ideal. Escuro = bebe mais.\n**Horário**: 500ml acordar, 250ml cada 2h, para 2h antes dormir.\nBaixa energia? 80% das vezes é desidratação."}'::jsonb, 85, 480, 'LLAMA', 0.75, 'system', 0),
('0ea61c7b89401365c7cfa0dbfc3fca1973a4055b4dc124f46338b61e6359e32c', 'Caminhada 10k passos emagrece quanto', 'caminhada 10k passos emagrece quanto', '{"texto": "10k passos = 8km = 400 cal gasto.\n30 dias = 12.000 cal = 1.5kg gordura.\n**Heurística 3x3**: 3km/h, 3x semana, 3 meses = 5kg.\nAcelera: Inclinação 5%, queima +30%. Mochila 5kg, +20%.\n**Não compensa** só caminhar se come 500 cal extra. Déficit manda."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('f23e4862dae9ae334655f258a30c7d01ec7256973e9c40c17e7b73c900668795', 'Alongamento 5min manhã rigidez', 'alongamento 5min manha rigidez', '{"texto": "Heurística: Movimento lubrifica fáscia.\nSequência 1min cada:\n1. **Gato-vaca**: Coluna, 10x.\n2. **Cobra**: Abre peito, fecha corcunda.\n3. **Pombo**: Glúteo, ciático.\n4. **Torção deitado**: Lombar.\n5. **Pescoço**: Orelha-ombro 30s cada.\nRigidez matinal cai 90%. Faz antes café."}'::jsonb, 87, 485, 'LLAMA', 0.75, 'system', 0),
('88dcdea98dd87bc08571e3d74704a3833897f8a154c9c2eed463ebbe6e7f1895', 'Sol vitamina D horário seguro quanto tempo', 'sol vitamina d horario seguro quanto tempo', '{"texto": "Heurística: UVB 10h-15h produz D. UVA resto queima.\nPele clara: 15min braço+perna, 11h ou 14h.\nPele escura: 45min mesmo horário.\n**Sem protetor**: Vitamina D não forma com FPS.\nInverno: Suplementa 2000UI/dia se exame <30ng.\nBenefício: Imunidade +50%, humor +30%."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('6c5f3cca57ab874bd4eeb5af5cca7d7c2fc4f9aeacc89c94c74cb2fb378ec8d1', 'Cafeína hora limite para não atrapalhar sono', 'cafeina hora limite para nao atrapalhar sono', '{"texto": "Heurística: Meia-vida 6h. Café 200mg 14h = 100mg 20h = 50mg 02h.\n**Corte**: 8-10h antes dormir. Dorme 22h = último café 12h-14h.\n**Dose**: 3mg/kg. 70kg = 210mg = 2 expressos.\n**Tolerância**: Pausa 7 dias cada 2 meses. Adenosina reseta.\nSintoma excesso: Ansiedade, tremor, insônia."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('32c3d51f16dc06f1a1e8167238741793ca38aaf143d6c58a85e29a678629f20c', 'Intestino preso resolver natural', 'intestino preso resolver natural', '{"texto": "Heurística: Água + Fibra + Movimento + Gordura.\n1. **Água 3L**: Fezes 75% água. Sem água vira pedra.\n2. **Fibra 30g**: Aveia, mamão, chia 2 colheres.\n3. **Gordura**: Azeite 1 colher jejum, lubrifica.\n4. **Agacha**: Banquinho pé, cólon reto.\n5. **Magnésio**: 400mg noite, puxa água intestino.\nResolve 90% casos 3 dias."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('f1e710c2619115e69b7db72172fd4ba4748ac75534c4f3da64290a48758ecb69', 'Dor cabeça tensional alívio 2min', 'dor cabeca tensional alivio 2min', '{"texto": "Heurística: Tensão trapézio comprime nervo.\n1. **Gelo nuca 30s**: Vasoconstrição, dor -40%.\n2. **Massagem trapézio**: Pinça músculo ombro-pescoço 30s cada.\n3. **Alongamento**: Orelha-ombro, segura 30s.\n4. **Água 500ml**: Desidratação causa 60% cefaleia.\n5. **Cafeína 100mg**: Vasodilatador se for enxaqueca.\nSoma: Dor some 80% casos."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('6cde3692b7d9df8f9966a522bbf8e086a7510373f8032957537df0e81e222609', 'Imunidade aumentar inverno protocolo', 'imunidade aumentar inverno protocolo', '{"texto": "Heurística: Vitamina D + Zinco + Sono + Estresse baixo.\n1. **Vit D 5000UI**: 2 meses, depois 2000UI.\n2. **Zinco 30mg**: Jejum 30 dias. Para vírus replicar.\n3. **Sono 8h**: Linfócito produz dormindo.\n4. **Alho cru 1 dente**: Allicin antibiótico natural.\n5. **Exercício**: 30min/dia, não >90min que imunodeprime.\nGripe cai 70%."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('e0f8183c59ffe05a0705ae062a17242320939049cf6a1bc9383b0d94a743d5e6', 'Vista cansada tela exercício 20-20-20', 'vista cansada tela exercicio 202020', '{"texto": "Heurística: Músculo ciliar trava perto.\nRegra 20-20-20: Cada 20min, olha 20 pés = 6m longe, 20s.\n**Pisca**: Tela reduz piscar 60%. Força 10x agora.\n**Distância**: Monitor 50-70cm.\n**Brilho**: Igual ambiente. Modo noturno após 18h.\n**Colírio**: Lágrima artificial sem conservante 4x/dia."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('d7ff06342dd2fc39d8098e624eed6bc104ec7cd615de887731b970250410b58d', 'Pressão alta baixar natural sem remédio', 'pressao alta baixar natural sem remedio', '{"texto": "Heurística: Sódio - Potássio - Estresse.\n1. **Sal <5g**: Tira saleiro mesa. 1 colher chá/dia total.\n2. **Potássio**: Banana, abacate, água coco. 3500mg/dia.\n3. **Caminhada 40min**: Vasodilata, cai 10mmHg.\n4. **Respiração 6/min**: 5s inspira, 5s expira, 10min.\n5. **Peso**: -5kg = -5mmHg.\n**Médico** se >160/100. Natural adjuvante."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('783fd31b42a90df9d5fb9fae416ed44e531b95524fdf0f4e05694f9508f141fa', 'Colesterol alto dieta o que comer evitar', 'colesterol alto dieta o que comer evitar', '{"texto": "Heurística: Fibra tira, saturada sobe.\n**Come**: Aveia beta-glucana, 40g/dia. Peixe ômega3 2x/semana. Nozes 30g. Azeite 2 colheres.\n**Evita**: Fritura, pele frango, queijo amarelo, embutido.\n**Ovo**: 1/dia ok, gema tem colina boa.\nExercício: 150min/semana sobe HDL 10%.\nLDL cai 20% em 90 dias."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('fbd3c23e62174856d24cb6985fa32d49d609644035d6ec0c0671f4ad1313aaba', 'Dor joelho exercício fortalece sem impacto', 'dor joelho exercicio fortalece sem impacto', '{"texto": "Heurística: Quadríceps fraco sobrecarrega joelho.\nSem dor aguda:\n1. **Agachamento parede**: Costas parede, desce 45°, 30s, 3x.\n2. **Elevação perna reta**: Deitado, sobe 30cm, 15x cada.\n3. **Ponte**: Glúteo, tira carga joelho, 20x.\n4. **Bicicleta**: Sem carga, lubrifica, 20min.\nEvita: Corrida, salto. Gelo 15min pós. Fortalece 6 semanas."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('3d6f7da62f0858dc2826e2f39a8590dc33fb4d0489b0a647bfb211aecc4aeedb', 'Metabolismo acelerar depois 30 anos', 'metabolismo acelerar depois 30 anos', '{"texto": "Heurística: Músculo = forno metabólico. -1% massa/ano após 30.\n1. **Treino força 3x**: Agachamento, terra, supino. +500g músculo = +50 cal/dia.\n2. **Proteína 1.6g/kg**: 70kg = 112g. Termogênese 30%.\n3. **NEAT**: Escada, anda telefone. 300 cal/dia invisível.\n4. **Sono 8h**: Dormir <6h cai leptina, fome +25%.\n5. **Água gelada**: 500ml queima 25 cal aquecer.\nSoma: +400 cal/dia = 15kg/ano."}'::jsonb, 97, 535, 'LLAMA', 0.75, 'system', 0),
('7cb27f692104be3098e30eaa30774fc0e69fca8751a172094bb378cdb38fefce', 'Cãibra noturna causa e solução', 'caibra noturna causa e solucao', '{"texto": "Heurística: Eletrólito + Hidratação + Alongamento.\nCausa: Magnésio/potássio baixo, desidratação, overtraining.\n**Solução aguda**: Estica músculo contraído, massa dura 30s.\n**Prevenção**: Magnésio dimalato 300mg noite. Banana pós treino. Água 35ml/kg.\n**Sabonete**: Mito. Funciona placebo 20%.\nSe diária: Exame médico, pode ser circulação."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('a06fe2d24ca3e4420597b1ea83f420bb6c13e0e3bb33d9522c1581373ee313a5', 'Varizes prevenir exercício circulação', 'varizes prevenir exercicio circulacao', '{"texto": "Heurística: Bomba panturrilha volta sangue.\n1. **Panturrilha 3x30**: De pé, sobe ponta pé. Faz fila banco.\n2. **Eleva perna**: Deita, perna parede 10min noite.\n3. **Evita**: Cruzar perna, salto >4h, calor.\n4. **Meia compressão**: Viagem >4h.\n5. **Peso**: -5kg tira pressão veia.\nGenética manda 60%, hábito 40%."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('d83e62e9d56b47464fd67a03e15eab873ba7c7bf0b61d19abd294f495318578d', 'Resfriado cortar 2 dias protocolo', 'resfriado cortar 2 dias protocolo', '{"texto": "Heurística: Ataca replicação viral 48h iniciais.\n1. **Zinco 75mg**: Pastilha cada 2h acordado. Corta duração 33%.\n2. **Vit C 2g**: Cada 6h. Saturação.\n3. **Vit D 50.000UI**: Dose única ataque.\n4. **Alho 2 dentes**: Amassa, espera 10min, engole.\n5. **Sono 9h**: Sistema imune dobra.\n6. **Zero açúcar**: Alimenta vírus.\nMelhora 80% em 48h. Se febre >39C médico."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('47ab3183a045a3e9aa0770721dcc73d5660bc99807ba608879f25add95321d0e', 'Ronco parar dormir parceiro', 'ronco parar dormir parceiro', '{"texto": "Heurística: Língua cai + via aérea estreita.\n1. **Emagrece 5%**: Gordura pescoço principal causa.\n2. **Dorme lado**: Costas língua cai. Bola tênis pijama costas.\n3. **Tira álcool**: Relaxa músculo 4h, ronca +200%.\n4. **Tira adesivo nasal**: Abre 30% via.\n5. **Exercício língua**: Encosta céu boca 3min/dia, fortalece.\n6. **Umidificador**: Seco irrita, incha.\nResolve 70% casos. Apneia = médico."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('79c0e55304bc140eedc1d93f5a56bf77d522e5104cccf2d84643b7577fdce57a', 'Detox digital domingo protocolo', 'detox digital domingo protocolo', '{"texto": "Heurística: Dopamina reset 24h.\n**Regra**: Domingo 8h-20h sem tela trabalho/lazer.\n**Pode**: Kindle, ligação voz, música.\n**Não pode**: Instagram, WhatsApp, Netflix, email.\n**Atividade**: Caminhada natureza 2h, cozinha receita nova, jogo tabuleiro, livro papel.\nSintoma: Tédio 2h, depois criatividade +200%. Segunda foco +40%."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('c3635e8c9f166d229312646615278c521f07ae93c80b71cbf4230473dce83468', 'Ansiedade crise parar 5 minutos técnica', 'ansiedade crise parar 5 minutos tecnica', '{"texto": "Heurística TIPP DBT: Temperatura + Intenso + Pausa + Progressivo.\n1. **Temperatura**: Gelo rosto 30s. Mergulho reflexo, FC -25%.\n2. **Intenso**: 20 polichinelo. Adrenalina gasta.\n3. **Pausa**: Respira 4-7-8, 4 ciclos.\n4. **Progressivo**: Contrai-relaxa músculo, pé pra cabeça.\n5. **Nomeia**: 5 vejo, 4 toco, 3 ouço, 2 cheiro, 1 gosto. Volta presente.\nCrise corta 90% em 5min."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('b3642a58e1e72c99cf95f5474c9266a26aa3d9d56b83f2118645548e0759963d', 'Procrastinação quebrar tarefa método 2 minutos', 'procrastinacao quebrar tarefa metodo 2 minutos', '{"texto": "Heurística: Resistência = tamanho tarefa percebido.\nRegra 2min: Se <2min, faz agora. Se >2min, faz SÓ 2min.\n`Escrever relatório` vira `Abrir Word e título`.\nCérebro: Começou = Zeigarnik, não gosta incompleto.\n80% continua após 2min.\n**Bônus**: Pomodoro 25min + recompensa 5min. Dopamina treina."}'::jsonb, 88, 490, 'LLAMA', 0.75, 'system', 0),
('334e66cedb49e9cec4fea8cebe341227c569da636d97a3489f8db4189a6e8e1f', 'Diário gratidão 3 coisas muda cérebro', 'diario gratidao 3 coisas muda cerebro', '{"texto": "Heurística: Foco treina filtro reticular.\nNoite: Escreve 3 coisas boas específicas hoje.\nNão: `Família`. Sim: `Café quente que filho fez 7h`.\n**Por quê**: Força escanear dia por positivo.\n30 dias: Viés negatividade cai 40%, serotonina +20%.\nApp: Presently ou caderno. 2min."}'::jsonb, 85, 475, 'LLAMA', 0.75, 'system', 0),
('6ad6bae65f9457b7d7418198962cf27017a3ae4f05ff630025d24fe87ccd758f', 'Pensamento negativo distorção cognitiva identificar', 'pensamento negativo distorcao cognitiva identificar', '{"texto": "Heurística TCC: Pensamento ≠ fato. 10 distorções:\n1. **Tudo-ou-nada**: `Sempre erro`.\n2. **Catastrofizar**: `Vou ser demitido`.\n3. **Leitura mente**: `Chefe me odeia`.\n4. **Adivinhação**: `Vai dar errado`.\n5. **Deveria**: `Eu deveria ser perfeito`.\n**Rebate**: Evidência contra? Conselho amigo? 1-10% verdade? Probabilidade real?\nPensamento cai força 70%."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('a91696c5675877f1125f73cb18695912a6e2a522edc4ffd1b61aac5e9300d1d7', 'Meditação 5min iniciante guiada', 'meditacao 5min iniciante guiada', '{"texto": "Heurística: Atenção = músculo, rep treina.\n1. **Senta**: Coluna reta, mão joelho.\n2. **Respira**: Natural, sem controlar.\n3. **Âncora**: Conta 1 inspira, 2 expira, até 10, repete.\n4. **Mente vagou**: Normal. Nota `pensando`, volta pro 1. Gentil.\n5. **Timer**: 5min. Não abre olho antes.\nBenefício: Amígdala -30% 8 semanas. App: Insight Timer."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('f69994359231bee4cf8af6b44263b260aec90871007c579b9206f014e42aad44', 'Limite dizer não sem culpa script', 'limite dizer nao sem culpa script', '{"texto": "Heurística: Não pro outro = Sim pra você.\nScript: `Agradeço convite. Não vou conseguir, tenho prioridade X. Adoraria outra vez`.\nNão: Justifica, desculpa, mente.\n**Teste**: Se sim dá ressentimento, é não.\nCulpa: 72h passa. Burnout dura anos.\nPratica: Não pequeno 1x/dia. Músculo cresce."}'::jsonb, 87, 485, 'LLAMA', 0.75, 'system', 0),
('fd327484ce43543f0c6dd84246e30d7be22d8899ecc5973a199b534b04eb12c6', 'Ciúme relacionamento controlar', 'ciume relacionamento controlar', '{"texto": "Heurística: Ciúme = insegurança projetada.\n1. **Nota gatilho**: Viu curtida, corpo reage. Pausa.\n2. **Fato vs história**: Fato: curtiu foto. História: `vai me trair`.\n3. **Necessidade**: Preciso segurança. Peço: `Me abraça?`.\n4. **Ação oposta**: Vontade fuçar = fecha app, caminha.\n5. **Terapia**: Se diária, raiz infância.\nRelação melhora 60% em 30 dias."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('e701bdd4bb2dcb7d5c25e9a45dbaa489c9f57bdee7db732a66b2bd4be43a6cb3', 'Perfeccionismo paralisa como soltar', 'perfeccionismo paralisa como soltar', '{"texto": "Heurística: 80% pronto > 100% nunca.\n1. **Define pronto**: 3 critérios objetivos. Bateu, envia.\n2. **Timer 30min**: Para quando tocar, mesmo feio.\n3. **Versão 1**: Nomeia rascunho. Cérebro aceita imperfeito.\n4. **Custo atraso**: 1 semana = R$ X perdido.\n5. **Mantra**: `Progresso, não perfeição`.\nProdutividade +200%. Ansiedade -50%."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('c89932f7e0de7d586182d272ff9c69af80923513b8ca6a2f81c01bdbc16d80e7', 'Raiva controlar antes explodir técnica', 'raiva controlar antes explodir tecnica', '{"texto": "Heurística: 6s entre estímulo-resposta.\n1. **Pausa**: Sente calor subir, STOP mental.\n2. **Sai**: `Volto em 10min`. Espaço físico quebra ciclo.\n3. **Água gelada**: Pulso, rosto. Vagus nerve.\n4. **Nomeia**: `Raiva nível 7`. Metacognição reduz 30%.\n5. **Volta**: Usa `Eu sinto` não `Você é`.\nRelação salva. Não diz coisa que 10 desculpa não apaga."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('f788e6d72bc9fb8e171bf3ea9b5418fab4b1254ef8ca2a1966057c80ef518358', 'Autoestima baixa exercício diário', 'autoestima baixa exercicio diario', '{"texto": "Heurística: Autoestima = evidência acumulada.\nNoite: 3 vitórias dia, micro que seja.\n`Fiz cama. Respondi email difícil. Não gritei no trânsito`.\n**Por quê**: Cérebro viés negativo, ignora 90% acerto.\n30 dias: Lista 90 provas contra `sou fracasso`.\nAção: Postura super-homem 2min manhã, testosterona +20%."}'::jsonb, 86, 480, 'LLAMA', 0.75, 'system', 0),
('fcf3397d4bcfd6b661d4e54d643be728102a2dfaadc3b9095eb8c9744b8249b0', 'Foco profundo 90min protocolo huberman', 'foco profundo 90min protocolo huberman', '{"texto": "Heurística: Ultradian rhythm 90min pico.\n1. **Bloqueia**: Fone, celular gaveta, aba única.\n2. **Cafeína 100mg**: 30min antes, Yerkes-Dodson.\n3. **Olha ponto**: Tela, 30s, pupila dilata, foco liga.\n4. **Trabalha 90min**: Sem pausa. Difícil primeiro.\n5. **Descanso 20min**: Caminhada sem input. Consolida.\n2 blocos/dia = 3h trabalho = 8h normal."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('60ebb8a0448943de4336c5308d6cd0f2e9e07f62f1313834015e550011cb055e', 'Luto fase aceitar exercício carta', 'luto fase aceitar exercicio carta', '{"texto": "Heurística: Não dito vira sintoma.\nEscreve carta pra quem perdeu: 1. **Raiva**: `Fiquei puto quando`. 2. **Tristeza**: `Doeu que`. 3. **Medo**: `Tenho medo de`. 4. **Culpa**: `Me culpo por`. 5. **Amor**: `Te amo porque`. 6. **Despedida**: `Te libero`.\n**Não envia**. Queima ou guarda.\nCérebro fecha ciclo. Dor -40% 1 sessão."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('d22ce0fffececf875c2e73774bf53e36dddf12f11dadaa738902275c5f709393', 'Comparação rede social parar', 'comparacao rede social parar', '{"texto": "Heurística: Highlight reel vs bastidor.\n1. **Desinstala 7 dias**: Detox dopamina. Tédio volta.\n2. **Deixa de seguir**: Gatilho inveja. Fica só aprende.\n3. **Limite**: 15min/dia app timer.\n4. **Antes postar**: Pergunta `Agrega ou ego?`.\n5. **Gratidão**: Após usar, lista 3 real.\nInveja cai 80%. Vida real parece boa de novo."}'::jsonb, 88, 490, 'LLAMA', 0.75, 'system', 0),
('d01f7d29cc4ff02313d1747d29defe38375d394327cb6dd6dafeb5e85d1fc0fd', 'TDAH adulto estratégia sem remédio', 'tdah adulto estrategia sem remedio', '{"texto": "Heurística: Cérebro busca dopamina, dá estrutura.\n1. **Externo**: Calendário, alarme, post-it. Memória trabalho fraca.\n2. **Corpo**: Exercício 30min manhã, dopamina +200% 3h.\n3. **Proteína**: 30g café, neurotransmissor.\n4. **Quebra**: Tarefa 25min, não 8h.\n5. **Ambiente**: Mesa limpa, fone ruído marrom.\n6. **Body double**: Trabalha junto, online serve.\nSintoma -50%. Médico se atrapalha vida."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('a5c9a46af3021a465429e3eb1600d27434e7cb11653cc87c016df32c14f54b14', 'Motivação sumiu como criar disciplina', 'motivacao sumiu como criar disciplina', '{"texto": "Heurística: Motivação segue ação, não precede.\n1. **2min regra**: Começa ridículo pequeno. Abre arquivo.\n2. **Identidade**: `Sou pessoa que treina`, não `tenho que`.\n3. **Ambiente**: Tênis lado cama. Fricção zero.\n4. **Rastreador**: X calendário, não quebra cadeia.\n5. **Contrato**: R$ 100 amigo se furar.\n21 dias vira automático. Motivação vira bônus."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('ed8fc7b4079833b61ed19c705cfe7f744e82c59c5e48a1ad78b8521e50857b88', 'Trauma infância identificar padrão adulto', 'trauma infancia identificar padrao adulto', '{"texto": "Heurística: Ferida cria estratégia sobrevivência que vira problema.\nAbandono → grude/ciúme. Rejeição → perfeccionismo. Humilhação → agressividade.\n**Pergunta**: Quando sinto X hoje, idade quantos anos parece?\n**Reescreve**: `Adulto cuida criança assustada`. Auto-compaixão.\n**Terapia**: EMDR, TCC reprocessa. Sozinho 20%, prof 80%."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('db8b3707ad0149f24fa40e9f50f17557e19e3d6184b2fd61f442a2c0b63000d9', 'Medo fracasso quebrar paralisia', 'medo fracasso quebrar paralisia', '{"texto": "Heurística: Fracasso = dado, não identidade.\n1. **Pior caso**: Escreve. `Perco R$ 5k`. Sobrevivo?\n2. **Melhor caso**: `Ganho R$ 50k`.\n3. **Mais provável**: `Aprendo X mesmo se der errado`.\n4. **Pré-mortem**: Lista 3 motivos falha, mitiga 1 hoje.\n5. **Teste pequeno**: R$ 100, não R$ 10k.\nAção cura medo. Análise paralisa."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('e442c2505fc44692978eb22b58e23254b58e48855a2d1ec75be5f5be9f5a709b', 'Síndrome impostor calar voz crítica', 'sindrome impostor calar voz critica', '{"texto": "Heurística: 70% pessoas sentem. Sinal que cresceu.\n1. **Arquivo elogio**: Pasta print feedback bom. Lê crise.\n2. **Fato vs sentimento**: Sente fraude. Fato: Formado, 3 anos exp, cliente renova.\n3. **Nomeia**: `Oi impostor, sei que quer proteger, mas tenho evidência`.\n4. **Fala**: Amigo mentor. Segredo perde força.\n5. **Ensina**: Explica tema, percebe quanto sabe.\nVoz baixa 60%."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('c260db50e853c70c7c2b392dc5d7ee02ca462120e9b5fea261234e9047d50e92', 'Decisão difícil matriz 10-10-10', 'decisao dificil matriz 101010', '{"texto": "Heurística: Emoção superestima curto prazo.\nPergunta sobre decisão: Como me sinto 10 dias? 10 meses? 10 anos?\nEx: Pedir demissão.\n10 dias: Medo, alívio.\n10 meses: Emprego novo ou arrependido.\n10 anos: Irrelevante se deu certo.\n**Escolhe** opção melhor 10-10-10, não 10 dias.\nArrependimento -80%."}'::jsonb, 88, 490, 'LLAMA', 0.75, 'system', 0),
('e9547c21ed49746814d699fcac2095a91904636431fbb80e149182eaf672549c', 'Regra 3-3-3 para mala viagem internacional', 'regra 333 para mala viagem internacional', '{"texto": "**Heurística 3-3-3**: 3 partes cima, 3 partes baixo, 3 sapatos. = 27 looks.\n**Cores**: Base neutra preta/azul/bege. 1 cor destaque.\n**Tecidos**: Não amassa = viscose, modal, jeans. Evita linho.\n**Bagagem mão**: 10kg = 5 dias. Técnica rolinho + cubo compressão.\n**API**: GET /airlines/baggage?airline=latam → 10kg mão + 23kg despachada.\n**Checklist**: Remédio, carregador, adaptador, cópia passaporte nuvem."}'::jsonb, 98, 535, 'LLAMA', 0.75, 'system', 0),
('04582247589a39ee0a568d2279f3b3c37eb9e3fa59abd592fd50af7aeaa1c426', 'Como achar passagem aérea 70% off', 'como achar passagem aerea 70 off', '{"texto": "**Heurística Skiplagged**: Voo com conexão + descarta último trecho. \nEx: SP→Miami R$ 3k. SP→Orlando c/ conexão Miami R$ 1k. Desce Miami.\n**Risco**: Só mala mão, 1 trecho, sem volta.\n**Seguro**: Google Flights > Explorar > Calendário. Dia verde.\n**API**: GET /flights/cheap?from=GRU&to=MIA&month=nov&flex=+-3\n**Truque**: Terça 1h manhã lança tarifa erro. Site Melhores Destinos."}'::jsonb, 102, 560, 'LLAMA', 0.75, 'system', 0),
('ffb441cc78aae6f9cd2875d1e544f055312aeecddd127a2d90b686d0b850c3a9', 'Seguro viagem internacional precisa mesmo', 'seguro viagem internacional precisa mesmo', '{"texto": "**Obrigatório**: Europa Schengen €30k, Cuba, Austrália.\n**Recomendado**: EUA saúde = R$ 10k/dia UTI.\n**Cobre**: Médico, mala, atraso voo, COVID.\n**Preço**: R$ 15/dia. R$ 150 10 dias.\n**Heurística**: Custo seguro < 3% viagem. <3% = faz.\n**API**: GET /insurance/quote?destination=europe&days=15&age=35\n**Hack**: Cartão Black já tem. Liga ativa."}'::jsonb, 96, 525, 'LLAMA', 0.75, 'system', 0),
('fa3d2b7d11079fff5c659484e5953f56a0cba1ca861ed17e1626facb87b3aa3e', 'Chip internacional vs roaming qual vale', 'chip internacional vs roaming qual vale', '{"texto": "**Roaming**: R$ 70/dia Claro. 10 dias = R$ 700. Roubo.\n**Chip**: Airalo eSIM 5GB R$ 80. Ativa antes embarcar.\n**WiFi**: Grátis mas inseguro. VPN obrigatório.\n**Heurística**: >3 dias = chip. <3 dias = roaming.\n**API**: GET /esim/plans?country=usa&data=5gb\n**Setup**: iPhone Ajustes > Celular > Adicionar eSIM. QR code."}'::jsonb, 93, 510, 'LLAMA', 0.75, 'system', 0),
('14c7352557ae8f19fa2631a113f4ca62d1dae6af6fd76d81a8d42621114e4e60', 'Milhas cartão melhor estratégia acumular', 'milhas cartao melhor estrategia acumular', '{"texto": "**Cartão**: Pão de Açúcar 1.5pt/R$. Anuidade grátis gasto R$ 3k.\n**Gasto**: Tudo no crédito, paga total. Boleto no 123milhas.\n**Transfer**: Bônus 100%. Espera Livelo→Smiles.\n**Heurística**: 1 milha = R$ 0,03. Venda R$ 25/milheiro.\n**Meta**: 100k milhas = ida-e-volta Europa executiva.\n**API**: GET /miles/promotions?program=smiles" }'::jsonb, 99, 540, 'LLAMA', 0.75, 'system', 0),
('532e6040ac1b8e5ddbf0b271bb59e0c7fa6aaf61e6b1b29e9f65dca41e2b473c', 'Imigração EUA perguntas resposta certa', 'imigracao eua perguntas resposta certa', '{"texto": "**Pergunta**: Motivo viagem? `Turismo 10 dias`.\n**Onde fica**: `Hotel X, reserva impressa`.\n**Quanto $**: `R$ 3k cash + cartão`.\n**Volta**: `Dia 20, passagem impressa`.\n**Trabalho**: `Empresa Y, carta férias`.\n**Heurística**: Resposta curta, verdade, documento prova. Nervoso = normal.\n**Não**: `Visitando namorado`, `procurando emprego`, celular desbloqueado.\n**Taxa recusa**: 3% BR."}'::jsonb, 97, 530, 'LLAMA', 0.75, 'system', 0),
('93a01b4f956731f139a10cfa8f7fcf9b205ea91f780df182b83734fe21489f6d', 'Mal de altitude Cusco soroche prevenir', 'mal de altitude cusco soroche prevenir', '{"texto": "**Cusco 3400m**: O2 -40%. Sintoma: dor cabeça, náusea.\n**Previne**: 1. Chega, dorme 1 dia. Não passeio. 2. Chá coca, não droga. 3. Diamox 125mg 12/12h, começa 2 dias antes. 4. Água 3L. 5. Evita álcool.\n**Heurística**: Sobe dormindo. Dorme Cusco, passeio Vale Sagrado 2800m, volta.\n**Grave**: Confusão, falta ar = desce 500m já.\n**API**: GET /health/altitude?city=cusco" }'::jsonb, 100, 550, 'LLAMA', 0.75, 'system', 0),
('04aee8845b2c181ad05f019f504dfe5a6b0bb939a84a44a5280fb610c5f578e6', 'Visto Europa ETIAS 2025 precisa', 'visto europa etias 2025 precisa', '{"texto": "**ETIAS**: Não é visto. Autorização online €7. Vale 3 anos.\n**Quando**: Inicia 2025. BR precisa.\n**Como**: Site oficial etias.europa.eu. 10min, aprova 96% na hora.\n**Heurística**: Passaporte válido 6 meses + ETIAS + €100/dia comprova.\n**Países**: 30 Schengen. UK não precisa.\n**API**: GET /visa/check?passport=BR&destination=FR" }'::jsonb, 94, 515, 'LLAMA', 0.75, 'system', 0),
('6e36b7f06abda760191faff1f10455cd2e6291dfd15375ec27a746f2df9035b6', 'Gorjeta países quanto dar não pagar mico', 'gorjeta paises quanto dar nao pagar mico', '{"texto": "**EUA**: 18-22% restaurante, $1/drink bar, $2 mala hotel.\n**Europa**: 5-10% se serviço bom. França couvert já inclui.\n**Japão**: ZERO. Ofensa dar.\n**Brasil**: 10% opcional. Pode tirar se ruim.\n**Heurística**: Dúvida = 10%. Cartão já vem. Dinheiro mão garçom.\n**API**: GET /culture/tips?country=japan" }'::jsonb, 91, 500, 'LLAMA', 0.75, 'system', 0),
('6203dea3e42aee781fef645760b3dd06fa8852be2ce89db933f3a9203d053657', 'Fuso horário jet lag acabar rápido', 'fuso horario jet lag acabar rapido', '{"texto": "**Leste**: Perde hora, pior. Ex: BR→Europa 4h.\n**Protocolo**: 1. Voo dorme horário destino. 2. Chega, sol manhã sem óculos 30min. 3. Melatonina 3mg 22h local 3 dias. 4. Cafeína só até 14h. 5. Exercício leve.\n**Heurística**: 1 dia ajuste por 1h fuso. 4h = 4 dias.\n**Oeste**: Ganha hora, fácil."}'::jsonb, 93, 510, 'LLAMA', 0.75, 'system', 0),
('777f92ef2804a07fd4d88fed1e284d459c0171f8779ca47abfba0acdb4222ac9', 'Vacina febre amarela onde tomar certificado', 'vacina febre amarela onde tomar certificado', '{"texto": "**País**: Colômbia, Bolívia, Angola exigem.\n**Onde**: Posto saúde SUS grátis. Leva RG+cartão SUS.\n**Certificado**: CIVP app Conecte SUS ou impresso.\n**Prazo**: 10 dias antes viagem. Vale vida toda.\n**Heurística**: Toma mesmo se não obrigatória. Mosquito não vê fronteira.\n**API**: GET /health/vaccine?country=colombia" }'::jsonb, 90, 495, 'LLAMA', 0.75, 'system', 0),
('7bd1cd2c1725bab28f9218a1e19a14bbb071ee06847099a56b0d93e5ab4ae736', 'Dinheiro vivo quanto levar viagem internacional', 'dinheiro vivo quanto levar viagem internacional', '{"texto": "**Regra**: 30% cash, 70% cartão.\nEuropa 10 dias: €300 cash + cartão Wise/Nomad.\n**Por quê**: Taxa cartão 4.5% IOF. Cash câmbio 1.8%.\n**Segurança**: Doleira cinto, hotel cofre, cópia nuvem.\n**Heurística**: <USD 10k não declara. >10k declara Alfândega.\n**Saque**: ATM aeroporto cobra €5. Centro melhor."}'::jsonb, 95, 520, 'LLAMA', 0.75, 'system', 0),
('4cb3b78e78374649cdf5a5a7122b9d5a0ddf1addcbee7bc4a173108ca78fb244', 'Overbooking voo o que fazer direitos', 'overbooking voo o que fazer direitos', '{"texto": "**Voluntário**: Companhia pede quem sai. Oferece $500-1000 + hotel. Aceita se flexível.\n**Involuntário**: ANAC 400. Direito: reacomoda próximo, hotel, alimentação, liga.\n**Heurística**: Chega cedo, faz check-in online, assento marcado = último tirado.\n**Compensação**: Atraso 4h+ = R$ 1k+ VRA.\n**API**: GET /flight/status?code=LA8001" }'::jsonb, 97, 530, 'LLAMA', 0.75, 'system', 0),
('ab3535e670873a6c4a5246329dbe7397e84e0c44548d3d28bb6357ad15de3868', 'Mala extraviada aeroporto passos', 'mala extraviada aeroporto passos', '{"texto": "1. **PIR**: Antes sair, balcão companhia. Protocolo.\n2. **Necessidade**: Compra essencial, guarda nota. Reembolso até $150/dia.\n3. **Prazo**: 21 dias acha ou paga. Até $1.800.\n4. **Seguro**: Aciona, cobre extra.\n5. **AirTag**: Coloca mala, rastreia. 90% acha.\n**Heurística**: Voo conexão + mala despachada = 5% perde. Só mão = 0%."}'::jsonb, 96, 525, 'LLAMA', 0.75, 'system', 0),
('04ce95ee35004bfe158079663d1eb5595cc687620a4157bde929116f4e4ada88', 'Hospedagem hotel vs airbnb quando vale', 'hospedagem hotel vs airbnb quando vale', '{"texto": "**Hotel**: <4 dias, quer serviço, café, segurança. Cancela fácil.\n**Airbnb**: >5 dias, família, cozinha, local. -30% preço.\n**Heurística**: Diária hotel < R$ 300 = hotel. > R$ 300 = Airbnb.\n**Custo oculto**: Airbnb taxa limpeza R$ 150 + caução.\n**API**: GET /compare?city=paris&checkin=2024-06-01&nights=7&guests=4\n**Avalia**: Nota >4.8 + >50 reviews."}'::jsonb, 99, 540, 'LLAMA', 0.75, 'system', 0),
('4c3f09b174a56c1ac171db2944aefb3eebf504c3d063aa5d9a0b4e089b908632', 'Carro alugar seguro precisa mesmo', 'carro alugar seguro precisa mesmo', '{"texto": "**CDW**: Colisão. Cartão cobre se recusar. Visa Infinite sim.\n**LDW**: Roubo. Mesma coisa.\n**Terceiro**: Obrigatório. R$ 30/dia.\n**Heurística**: Recusa tudo, usa cartão. Imprime apólice inglês.\n**Cuidado**: Arranhão roda = R$ 800. Foto tudo antes.\n**API**: GET /car/rental?city=MCO&pickup=2024-07-01&insurance=none" }'::jsonb, 94, 515, 'LLAMA', 0.75, 'system', 0),
('ee998f73042e761e3adb99ca09beea09ce137c01971f95dd73738ba592dc6286', 'Roteiro 7 dias Europa primeira vez', 'roteiro 7 dias europa primeira vez', '{"texto": "**Regra**: 1 base, bate-volta. 3 cidades = 3 check-in.\n**Dia 1-4**: Paris. Torre, Louvre, Versalhes.\n**Dia 5**: Bate-volta Bruxelas trem 1h30.\n**Dia 6-7**: Amsterdã trem 3h.\n**Heurística**: 2h desloca = 1 dia perdido. Voo = 5h porta-porta.\n**API**: GET /train?from=paris&to=amsterdam&date=2024-06-05\n**Custo**: € 1.200 total."}'::jsonb, 98, 535, 'LLAMA', 0.75, 'system', 0),
('570d3b4e5831fff078c9a2efbcaf72d9ae695264c000324e1e2a97515bc6743f', 'Comida rua exterior seguro comer', 'comida rua exterior seguro comer', '{"texto": "**Heurística Fila**: Local come = seguro. Fila grande = giro.\n**Regra**: Cozido na hora >80°C mata bactéria.\n**Evita**: Salada crua, gelo, sorvete, fruta descascada. Água só garrafa.\n**Kit**: Imosec, probiótico, álcool gel.\n**Diarreia**: Soro caseiro 1L água + 1c açúcar + 1c sal.\n**Seguro**: Tailândia, México ok. Índia risco."}'::jsonb, 93, 510, 'LLAMA', 0.75, 'system', 0),
('fadc763ecc48dfac00f86179e4ec7d0b184f226f484c0684bc7501aabcbbdad4', 'Foto viagem celular configuração melhor', 'foto viagem celular configuracao melhor', '{"texto": "**Hora dourada**: 1h após nascer, 1h antes pôr. Luz suave.\n**Regra terços**: Horizonte 1/3 cima ou baixo.\n**RAW**: iPhone Ajustes > Câmera > Apple ProRAW. Edita melhor.\n**Lente**: 0.5x paisagem, 1x geral, 3x detalhe.\n**Heurística**: Limpa lente. 90% foto ruim = dedo.\n**Backup**: Google Fotos 15GB grátis."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('8eb2907156f7e8c66a423d1cf13fa4ae345bd513833212f238bb05dc5d7fb8f2', 'Roteiro 5 dias Nova York barato', 'roteiro 5 dias nova york barato', '{"texto": "**Dia 1**: Times Square, Central Park, Museu Met $0 sex 17h.\n**Dia 2**: Estátua ferry Staten Island grátis, Wall St, 9/11.\n**Dia 3**: Brooklyn Bridge, Dumbo, Williamsburg.\n**Dia 4**: High Line, Chelsea Market, Broadway TKTS 50%.\n**Dia 5**: 5th Ave, Biblioteca, Grand Central.\n**Custo**: Hotel R$ 400/dia, comida R$ 150/dia, metro $34/semana.\n**API**: GET /hotels?city=NYC&max_price=200" }'::jsonb, 100, 550, 'LLAMA', 0.75, 'system', 0),
('1422defffec9eafa5396e374035054b9d468e8ce5f9ba7ae0f65175c034865d5', 'Roteiro 7 dias Japão primeira vez', 'roteiro 7 dias japao primeira vez', '{"texto": "**Dia 1-3**: Tóquio. Shibuya, Asakusa, Akihabara.\n**Dia 4**: Hakone bate-volta, Fuji, onsen.\n**Dia 5-7**: Kyoto trem-bala. Fushimi, Arashiyama, Gion.\n**JR Pass**: 7 dias R$ 1.500. Compensa se Tóquio-Kyoto ida-volta.\n**Comida**: 7-Eleven 500 ienes. Ichiran ramen.\n**API**: GET /flights?from=GRU&to=NRT&month=april\n**Sakura**: Abril. Outono: Novembro."}'::jsonb, 102, 560, 'LLAMA', 0.75, 'system', 0),
('1d91454889de64f8b24260cba3a576bf4da6cc2b6a11cbf49de830eed21ff1b1', 'Roteiro 10 dias Itália clássica', 'roteiro 10 dias italia classica', '{"texto": "**Dia 1-3**: Roma. Coliseu, Vaticano, Trastevere.\n**Dia 4-5**: Florença trem 1h30. Davi, Uffizi.\n**Dia 6**: Pisa bate-volta.\n**Dia 7-8**: Veneza trem 2h. Gôndola cara, vaporetto €9.\n**Dia 9-10**: Milão. Duomo, Lago Como.\n**Heurística**: Trem Italo .it mais barato que Trenitalia.\n**Custo**: € 120/dia médio."}'::jsonb, 99, 540, 'LLAMA', 0.75, 'system', 0),
('14632212ed07c8dded75692877e5ca448ebe7ce777fdf3b6d5c1d7e264f70c88', 'Roteiro Atacama 4 dias deserto', 'roteiro atacama 4 dias deserto', '{"texto": "**Base**: San Pedro. 2400m altitude.\n**Dia 1**: Aclimata, Vale da Lua pôr do sol.\n**Dia 2**: Gêiser Tatio 4h manhã -15°C. Almoço Termas Puritama.\n**Dia 3**: Lagunas Altiplânicas 4200m + Salar.\n**Dia 4**: Vale Arco-Íris.\n**Agência**: R$ 800 pacote 3 dias. Fecha lá -50%.\n**API**: GET /tours?city=sanpedro&days=3\n**Leva**: Protetor 60, roupa frio calor."}'::jsonb, 97, 530, 'LLAMA', 0.75, 'system', 0),
('6848d35f28b01dee281d96adab7e5702ee17747954529af5cf632a46ce5f9cd3', 'Roteiro Patagônia Argentina 7 dias', 'roteiro patagonia argentina 7 dias', '{"texto": "**El Calafate**: 3 dias. Perito Moreno, navegação.\n**El Chaltén**: 4 dias. Laguna de los Tres, Fitz Roy.\n**Quando**: Out-Mar. Jan lotado.\n**Voos**: SP-El Calafate via BUE R$ 3k.\n**Heurística**: Vento 100km/h. Leva corta-vento.\n**Custo**: R$ 8k total.\n**API**: GET /flights?from=GRU&to=FTE" }'::jsonb, 96, 525, 'LLAMA', 0.75, 'system', 0),
('270b2aa25b9aaf8c76ac179b545b2c76747f7f880fef6c2fda1ba744aba8f317', 'Roteiro Machu Picchu sem agência', 'roteiro machu picchu sem agencia', '{"texto": "**Cusco-Lima**: Bus 22h $30 ou voo $80.\n**Cusco-Ollantaytambo**: Van 2h 10 soles.\n**Trem**: PeruRail $70 ida. Compra 60 dias antes.\n**Entrada**: R$ 250 site oficial. Esgota 3 meses.\n**Trilha**: Hidrelétrica 3h caminhada, $20. Aventura.\n**Total**: R$ 1.200 vs R$ 2.500 agência.\n**API**: GET /train?from=ollantaytambo&to=aguascalientes" }'::jsonb, 98, 535, 'LLAMA', 0.75, 'system', 0),
('28e17de5a7674aafdb1fa18d0bd5713c904b75c70afc3be14934c70b2e757a46', 'Roteiro Nordeste 15 dias carro', 'roteiro nordeste 15 dias carro', '{"texto": "**Rota**: Maceió 3d → Maragogi 2d → Porto Galinhas 3d → Recife 2d → João Pessoa 2d → Natal 3d.\n**Km**: 800km. Gasolina R$ 600.\n**Pedágio**: R$ 50.\n**Heurística**: 200km/dia máx. Para praia no meio.\n**Pousada**: R$ 200 casal. Reserva Booking.\n**API**: GET /hotels?route=maceio-natal&days=15\n**Melhor**: Agosto, vento, sem chuva."}'::jsonb, 100, 550, 'LLAMA', 0.75, 'system', 0),
('b0398ab77a28e3f26c404fd85c9d7114bbb62ec8d7ebd9898744c6ec0b17913f', 'Roteiro Chapada Diamantina 5 dias', 'roteiro chapada diamantina 5 dias', '{"texto": "**Base**: Lençóis. Voo Salvador-Lençóis 1h.\n**Dia 1**: Cachoeira Fumaça trilha 6h.\n**Dia 2**: Poço Azul + Encantado.\n**Dia 3**: Gruta Lapa Doce + Pratinha.\n**Dia 4**: Morro Pai Inácio pôr do sol.\n**Dia 5**: Ribeirão do Meio.\n**Guia**: R$ 200/dia grupo. Obrigatório Fumaça.\n**API**: GET /tours?city=lencois\n**Leva**: Bota, repelente, lanterna."}'::jsonb, 97, 530, 'LLAMA', 0.75, 'system', 0),
('df5be07b1900fe0c683f6b9486d02397ec3ce3201c20e6d817602852bff46338', 'Roteiro Bonito MS 4 dias', 'roteiro bonito ms 4 dias', '{"texto": "**Dia 1**: Gruta Lago Azul + Rio da Prata flutuação.\n**Dia 2**: Abismo Anhumas rapel 72m.\n**Dia 3**: Buraco das Araras + Boca da Onça.\n**Dia 4**: Estância Mimosa cachoeiras.\n**Vouch**: Obrigatório, compra agência. R$ 300/dia passeio.\n**Quando**: Dez-Mar água cristalina. Julho frio.\n**API**: GET /vouchers?city=bonito" }'::jsonb, 96, 525, 'LLAMA', 0.75, 'system', 0),
('f027b528a2a57741947c8619aaeb9e999d01979f718cd329456d287ae601cacd', 'Roteiro Amazônia Manaus 5 dias', 'roteiro amazonia manaus 5 dias', '{"texto": "**Dia 1**: Teatro Amazonas + Mercado Adolpho.\n**Dia 2-4**: Lodge Anavilhanas. Encontro águas, boto, jacaré, tribo.\n**Dia 5**: MUSA torre.\n**Lodge**: R$ 800/dia tudo incluído. Fecha pacote.\n**Malária**: Manaus urbano não. Selva leva repelente.\n**API**: GET /lodge?region=anavilhanas\n**Melhor**: Jun-Nov seca, praia rio."}'::jsonb, 95, 520, 'LLAMA', 0.75, 'system', 0),
('4d12aeea83b4cc1fc6f785ba0653848c5e91086e1a35485c8fa37075a1aef708', 'Roteiro Foz do Iguaçu 3 dias', 'roteiro foz do iguacu 3 dias', '{"texto": "**Dia 1**: Cataratas BR + Parque Aves.\n**Dia 2**: Cataratas AR + Gran Aventura barco.\n**Dia 3**: Itaipu + Marco 3 Fronteiras.\n**Ingresso**: R$ 100 BR, AR 50% mais caro. Compra site.\n**Hospeda**: Centro, R$ 150/dia.\n**API**: GET /tickets?attraction=iguazu&side=br\n**Capa**: Sempre. 275 quedas molha."}'::jsonb, 93, 510, 'LLAMA', 0.75, 'system', 0),
('c105808281fa52953b03306dbb8ffe9a072dd4f884e9374896e23d834f28a412', 'Roteiro Gramado Canela 4 dias inverno', 'roteiro gramado canela 4 dias inverno', '{"texto": "**Julho**: 5°C, geada. Leva casaco.\n**Dia 1**: Lago Negro + Rua Coberta + fondue.\n**Dia 2**: Snowland + Mundo Gelado.\n**Dia 3**: Canela Catedral + Parque Caracol.\n**Dia 4**: Vinícola Vale dos Vinhedos 2h.\n**Custo**: R$ 500/dia casal. Fondue R$ 200.\n**API**: GET /hotels?city=gramado&month=july\n**Reserva**: 3 meses antes. Lota."}'::jsonb, 94, 515, 'LLAMA', 0.75, 'system', 0),
('f5fff35b6d5d6e8622d64928f9dae9dfaf62aa67448877324b8721a8c65b0db6', 'Roteiro Jalapão 5 dias 4x4', 'roteiro jalapao 5 dias 4x4', '{"texto": "**Expedição**: Sai Palmas. 4x4 obrigatório.\n**Dia 1**: Cachoeira Velha.\n**Dia 2**: Fervedouros Bela Vista, Ceiça.\n**Dia 3**: Dunas pôr do sol.\n**Dia 4**: Cachoeira Formiga.\n**Dia 5**: Volta Palmas.\n**Pacote**: R$ 2.500 tudo incluído. Sozinho gasta igual.\n**API**: GET /tours?city=palmas&dest=japalao\n**Sinal**: Zero. Desconecta."}'::jsonb, 96, 525, 'LLAMA', 0.75, 'system', 0),
('3ece978cdbca0f78fc1c4429902d085214db3358c54dd95c6d916f5cdff79f15', 'Roteiro Fernando de Noronha 7 dias', 'roteiro fernando de noronha 7 dias', '{"texto": "**Taxa**: R$ 100/dia TPA + R$ 330 parque. Paga online.\n**Dia 1-2**: Praia Sancho, Baía Porcos.\n**Dia 3**: Mergulho batismo R$ 300.\n**Dia 4**: Passeio barco golfinho.\n**Dia 5**: Trilha Atalaia piscina natural.\n**Dia 6**: Forte, pôr sol.\n**Dia 7**: Compras.\n**Custo**: R$ 8k total. **API**: GET /flights?to=FEN\n**Buggy**: R$ 300/dia aluga."}'::jsonb, 98, 535, 'LLAMA', 0.75, 'system', 0),
('610fe356281a6ab7da386db20fc424c3ea4d645cde8ce4238ad69c8711ae6505', 'Roteiro Dubai 5 dias luxo barato', 'roteiro dubai 5 dias luxo barato', '{"texto": "**Dia 1**: Burj Khalifa 124 andar $40 + Dubai Mall + fonte.\n**Dia 2**: Deserto safári $50 jantar incluído.\n**Dia 3**: Marina, JBR praia pública, Madinat.\n**Dia 4**: Abu Dhabi bate-volta mesquita $30 bus.\n**Dia 5**: Ouro mercado + Creek abra R$ 1.\n**Hotel**: R$ 300 Deira. Táxi caro, metro $2.\n**API**: GET /hotels?city=dubai&budget=100\n**Álcool**: Só hotel."}'::jsonb, 99, 540, 'LLAMA', 0.75, 'system', 0),
('e97a9b41e0b492a4b9ee93672613021a02b36a266f71531be38b2b109ec71eee', 'Roteiro Maldivas barato 7 dias', 'roteiro maldivas barato 7 dias', '{"texto": "**Hack**: Ilha local Maafushi, não resort.\n**Hotel**: R$ 300/dia café. Resort R$ 3k.\n**Passeio**: Resort day-use $100. Snorkel $30.\n**Voo**: SP-Malé R$ 5k. Barco público $2.\n**Total**: R$ 7k vs R$ 30k resort.\n**Bikini**: Só praia turista. Local cobre.\n**API**: GET /hotels?city=maafushi\n**Melhor**: Nov-Abr seco."}'::jsonb, 100, 550, 'LLAMA', 0.75, 'system', 0),
('e237539873c5992462a7dd5ed1c20e319d37b2efc1465ec188efd695533c0c30', 'Roteiro Tailândia 15 dias mochilão', 'roteiro tailandia 15 dias mochilao', '{"texto": "**Norte 5d**: Bangkok templo, mercado. Chiang Mai templo, elefante ético.\n**Sul 10d**: Phuket, Phi Phi, Krabi Railay.\n**Bus**: Noturno VIP R$ 80. Voo interno R$ 200.\n**Custo**: R$ 150/dia. Pad Thai R$ 10.\n**Golpe**: Tuktuk, joia. Pechincha 50%.\n**API**: GET /flights?from=BKK&to=HKT\n**Visto**: Não precisa 90 dias."}'::jsonb, 101, 555, 'LLAMA', 0.75, 'system', 0),
('8d6e2c5dc87aa2efd7adef15409da9b7a544df3f550eb7427f33d4c358b07d71', 'Roteiro Egito 8 dias clássico', 'roteiro egito 8 dias classico', '{"texto": "**Dia 1-3**: Cairo. Pirâmide, Museu, Khan el Khalili.\n**Dia 4-7**: Cruzeiro Nilo Luxor-Aswan. R$ 1.500 tudo incluído.\n**Dia 8**: Abu Simbel.\n**Gorjeta**: Obrigatória, $1 tudo.\n**Roupa**: Ombro/joelho coberto templo.\n**API**: GET /cruise?river=nile&days=4\n**Seguro**: Essencial. Calor 45°C."}'::jsonb, 97, 530, 'LLAMA', 0.75, 'system', 0),
('71fc86057d473eeaec21641bd4c59fd96a34a0f9f34f15cfd9037eed90df494b', 'Roteiro Grécia ilhas 10 dias', 'roteiro grecia ilhas 10 dias', '{"texto": "**Dia 1-3**: Atenas. Acrópole, Plaka.\n**Dia 4-6**: Santorini. Oia pôr sol, Red Beach. €50/noite.\n**Dia 7-10**: Mykonos. Paradise Beach, Little Venice.\n**Ferry**: Rápido €60, lento €30. Reserva.\n**API**: GET /ferry?from=athens&to=santorini\n**Melhor**: Jun/Set. Jul-Ago lotado caro.\n**Custo**: €100/dia."}'::jsonb, 98, 535, 'LLAMA', 0.75, 'system', 0),
('8a2d740b81d776eddc57a0a9dff4820be9ef009e27fe764a9d5c55c67ada71c5', 'Roteiro África do Sul 12 dias safári', 'roteiro africa do sul 12 dias safari', '{"texto": "**Dia 1-3**: Cape Town. Table Mountain, pinguim, vinícola.\n**Dia 4-5**: Garden Route carro.\n**Dia 6-9**: Kruger safári. Self-drive R$ 500/dia.\n**Dia 10-12**: Joanesburgo, Soweto.\n**Malária**: Kruger risco baixo inverno.\n**API**: GET /safari?park=kruger&days=3\n**Custo**: R$ 12k total.\n**Uber**: Seguro dia."}'::jsonb, 100, 550, 'LLAMA', 0.75, 'system', 0),
('77ca977e8bd52c1ded5714615b0f9b53e0d9e19e77d77c051550e400d2091c49', 'Erro tarifa aérea como achar', 'erro tarifa aerea como achar', '{"texto": "**Site**: Secret Flying, Melhores Destinos, Passagens Imperdíveis.\n**Alerta**: Google Flights rastreia preço.\n**Regra**: Compra já. Erro dura 2h. Cia pode cancelar, reembolsa.\n**Ex**: SP-NY R$ 800 ida-volta. Normal R$ 3k.\n**Heurística**: Madrugada ter/quarta lança.\n**API**: GET /flights/error-fare?from=GRU" }'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('785399f6e09d330a753bf6655da9c7bc58ed1afb0715dbe68e5f5e7c3159a530', 'Casa de graça house sitting como', 'casa de graca house sitting como', '{"texto": "**Site**: TrustedHousesitters $130/ano. Cuida casa+pet, mora grátis.\n**Perfil**: Ref 3, vídeo, polícia.\n**Aplica**: 5/dia. Europa, EUA, AU.\n**Economia**: R$ 10k/mês hotel.\n**Heurística**: Natal/Ano Novo = alta demanda. 3 meses antes.\n**Seguro**: Site cobre R$ 50k dano."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('9861ab52ea0ac0e61514ef5ff939fc1fb47cc354ad71d4fa6195230c6c09566d', 'Trabalhar viagem nômade digital visto', 'trabalhar viagem nomade digital visto', '{"texto": "**País**: Portugal D7, México 180 dias, Tailândia DTV 5 anos, Dubai 1 ano.\n**Renda**: Comprova R$ 15k/mês.\n**Imposto**: Portugal NHR 10 anos 20%. Dubai 0%.\n**Heurística**: Base 3 meses, evita turista.\n**Custo**: Lisboa R$ 12k/mês. Chiang Mai R$ 5k.\n**API**: GET /visa?type=nomad&income=3000" }'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('eb2a4fa98f7016bd83e420783210a698d8d876ba7f054ce7890a0be1b9058e59', 'Upgrade voo grátis como conseguir', 'upgrade voo gratis como conseguir', '{"texto": "**Veste**: Social, não chinelo.\n**Chega**: Cedo, balcão pergunta educado: `Overbook? Topo voluntário se precisar`.\n**Fidelidade**: Ouro+ prioridade.\n**Aniversário**: Menciona. Lua mel.\n**Heurística**: Voo lotado + sozinho = chance 20%.\n**Não**: Exige. Pediu = não ganha.\n**Alternativa**: Leilão upgrade app cia R$ 300."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('27ca23eb2cde8367dc8db888fa1b3db944b33ccf5c9e6ff8ffa1e5bc4124f96a', 'Diagnóstico financeiro dívida total juros método avalanche', 'diagnostico financeiro divida total juros metodo avalanche', '{"texto": "**Passo 1: Raio-X**\nLista todas dívidas: Credor | Valor | Juros a.m | Parcela mínima\nEx: Nubank R$5k | 14% | R$500 | Cartão R$8k | 15% | R$800\n**Passo 2: Ordena** Maior juros primeiro, não maior valor.\n**Passo 3: Avalanche** Paga mínimo todas. Todo extra joga na maior juros.\n**Heurística**: R$1k extra/mês em dívida 15% a.m = economiza R$4.200 juros ano.\n**Meta**: Zera cartão 8 meses vs 24 meses bola neve.\n**Planilha**: /template/avalanche.xlsx" }'::jsonb, 98, 540, 'LLAMA', 0.75, 'system', 0),
('fb728ba2e5b746176906f949f98420bf1a3d990e3940ebb4513c21d531c58e7d', 'Plano negócio 1 página anti-dívida canvas', 'plano negocio 1 pagina antidivida canvas', '{"texto": "**Canvas 1P Anti-Dívida**\n1. **Problema**: Minha dívida R$ X me custa R$ Y/mês juros.\n2. **Solução**: Negócio gera R$ Z/mês líquido em 90 dias.\n3. **Cliente**: Quem paga HOJE pelo que sei fazer? Ex: vizinho paga bolo.\n4. **Oferta**: Produto R$ 20, custo R$ 8, lucro R$ 12. Precisa vender 250/mês = R$ 3k.\n5. **Canal**: WhatsApp status, porta-porta, feira.\n6. **Métrica**: Venda dia, caixa dia. Se < R$ 100, muda.\n7. **Custo**: Começa R$ 0-200. Sem empréstimo.\n**Handoff**: Preenche → executa 7 dias → mede."}'::jsonb, 102, 560, 'LLAMA', 0.75, 'system', 0),
('2de66dfd40e288fbba72a93684b58bb9afcdfd0150fe712ae78c1a415cad42f8', 'Escolher negócio certo para quitar dívida rápido', 'escolher negocio certo para quitar divida rapido', '{"texto": "**Matriz 3F**: Frequência + Fácil + Fluxo\n**Frequência**: Cliente compra todo mês? Marmita sim, sofá não.\n**Fácil**: Sei fazer hoje sem curso? Sim = 0 custo.\n**Fluxo**: Recebe na hora ou 30 dias? PIX > boleto.\n**Top 5**: 1. Comida R$ 15 ticket. 2. Limpeza faxina R$ 120. 3. Aula reforço R$ 50/h. 4. Manicure R$ 40. 5. Dog walk R$ 25.\n**Descarta**: Loja, estoque, aluguel. Dívida + dívida = falência.\n**Teste**: Vende 10 antes abrir CNPJ."}'::jsonb, 100, 550, 'LLAMA', 0.75, 'system', 0),
('1b6cabf3eab45e5ae1294b3e347cc75a7bdea376da66f303d54f312829443201', 'Meta SMART quitar R$ 10 mil em 6 meses', 'meta smart quitar r 10 mil em 6 meses', '{"texto": "**S**pecific: Quitar R$ 10k cartão Nubank.\n**M**easurable: R$ 1.667/mês ou R$ 417/semana.\n**A**ttainable: Negócio marmita lucro R$ 15 x 28 dias = R$ 420/semana.\n**R**elevant: Juros 15% a.m = R$ 1.5k/mês dreno.\n**T**ime: 6 meses data X.\n**Plano**: Semana 1-2: valida. 3-8: escala. 9-24: mantém.\n**Controle**: Planilha /controle/metas. Verde = dia meta. Vermelho = dobra amanhã."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('9730dc8978bd148d83ece117acb5cd30eccdf5a11d205af63c72ee1906d84aff', 'Organizador financeiro 50-30-20 dívida adaptado', 'organizador financeiro 503020 divida adaptado', '{"texto": "**Normal**: 50% necessidade, 30% desejo, 20% investe.\n**Dívida**: 50% necessidade, 20% desejo, 30% DÍVIDA.\nRenda R$ 3k: R$ 1.5k sobrevive, R$ 600 lazer, R$ 900 dívida.\n**Heurística**: Desejo vira extra dívida se >15% juros.\n**App**: Organizze, Mobills, Notion template.\n**Alerta**: Gasto desejo >20% 3 meses = corta cartão.\n**Handoff**: Copia /template/50-30-20-divida" }'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('4c068eef02bdc94270c8104cac791863bf77db5ce2ba708fb8fcf243d8529d64', 'Fluxo de caixa diário negócio micro', 'fluxo de caixa diario negocio micro', '{"texto": "**Caderno 3 colunas**: Data | Entrada | Saída | Saldo\n**Regra**: Anota na hora. Esquece = fura.\n**Fechamento**: 20h soma dia. Saldo < R$ 50 = alerta.\n**Separação**: PF conta A, PJ conta B. Mistura = falência.\n**Heurística**: 28 dias positivo = negócio viável. 28 negativo = fecha.\n**Digital**: SumUp conta PJ grátis. Extrato = fluxo.\n**Meta**: Caixa 30 dias custo fixo."}'::jsonb, 97, 535, 'LLAMA', 0.75, 'system', 0),
('8b313959422d14b24f09296cc0f9c40ce2741e332c0cb139faea29f70c94806a', 'Precificar produto lucro 100% dívida', 'precificar produto lucro 100 divida', '{"texto": "**Fórmula**: Custo Total x 2 = Preço mínimo.\nCusto: Material R$ 5 + Gás R$ 1 + Embalagem R$ 1 + Hora R$ 3 = R$ 10.\nPreço: R$ 20. Lucro: R$ 10 = 100%.\n**Heurística**: <50% lucro = escravo. >200% = não vende.\n**Teste**: Posta R$ 25. Vende 10? Mantém. Vende 0? Volta R$ 20.\n**Meta**: R$ 10 lucro x 300/mês = R$ 3k pra dívida.\n**Planilha**: /template/preco" }'::jsonb, 99, 545, 'LLAMA', 0.75, 'system', 0),
('c807f8f29fb4ef018e0b5ced5bf7a537398bc2fba71fc57e91a8a244fa81d207', 'Renegociar dívida desconto 90% script', 'renegociar divida desconto 90 script', '{"texto": "**Script**: `Olá, CPF X. Quero quitar à vista. Qual desconto máximo? Pago hoje`.\n**Heurística**: Dívida >1 ano = banco já deu perda. Aceita 10-20%.\nR$ 10k vira R$ 1.5k.\n**Não**: Parcela. Juro volta.\n**Onde**: Serasa Limpa Nome feirão, telefone banco, Procon.\n**Comprova**: Pede carta quitação. Guarda 5 anos.\n**Economia**: R$ 8.5k vira capital giro negócio."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('86a512538c2f9bd683abe2fad9ba5f1e0f9a05ba9acff8501360becfd1b508b5', 'MEI abrir grátis passo a passo dívida', 'mei abrir gratis passo a passo divida', '{"texto": "**Gov.br**: gov.br/mei. 10min grátis.\n**CNAE**: Escolhe 1 principal + 15 secundária. Ex: 5611-2/03 Marmitaria.\n**DAS**: R$ 71/mês. Paga dia 20.\n**Limite**: R$ 81k/ano = R$ 6.750/mês.\n**Heurística**: Fatura > R$ 3k/mês = abre. < R$ 3k = espera.\n**Dívida**: Abre mesmo negativado. CNPJ limpo.\n**Conta PJ**: C6, Inter zero tarifa. Separa dinheiro."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('fd1a17310279e87407df5026e85db382b1a8184eb775e1076f89fb695d732d1f', 'Capital giro zero começar vender', 'capital giro zero comecar vender', '{"texto": "**Modelo**: Venda antes, compra depois.\n**Marmita**: Posta cardápio segunda. Cliente paga PIX terça. Compra quarta. Entrega quarta.\n**Serviço**: 50% entrada. Compra material.\n**Encomenda**: Mínimo 10 unidades. Não faz 1.\n**Heurística**: R$ 0 investido, R$ 0 risco. Lucro = capital giro.\n**Escala**: Lucro 30 dias vira estoque 5 dias.\n**Não**: Empréstimo pra começar."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('51e68a65989c3922601ee5eeaefffcdcd0df749d1012a92c2410fef47e1eb62f', 'Controlar ansiedade financeira técnica', 'controlar ansiedade financeira tecnica', '{"texto": "**Causa**: Incerteza + impotência.\n**Técnica 5-4-3-2-1**: 5 vê, 4 toca, 3 ouve, 2 cheira, 1 prova. Volta presente.\n**Plano**: Escreve pior caso. R$ 0. Sobrevive? Sim. Ansiedade -50%.\n**Ação**: 1 micro-passo 5min. Liga credor, anota gasto.\n**Heurística**: Ansiedade = energia sem ação. Ação = alívio.\n**Limite**: Ataca pânico = CVV 188. Não é fraqueza."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('23d3819c790bdbee4bdebc993d4ad09a429c84b595658f2c0ec58756e42c37a1', 'Meta diária venda bater dívida', 'meta diaria venda bater divida', '{"texto": "**Conta**: Dívida R$ 12k / 180 dias = R$ 67/dia.\nLucro R$ 10/un = 7 vendas/dia.\n**Painel**: Papel parede. 7 quadrados/dia. Vendeu = X. 7X = ganhou.\n**Heurística**: Visual > digital. Cérebro vicia em completar.\n**Se não bate**: Liga 5 cliente antigo. `Oi, sumida. Quer X hoje?`\n**Prêmio**: Bate 7 dias = 1 folga. Não bate = 0 folga."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('79ed6fe25dd4d8ddab6dd88ee3865e7b29f9cec5889177b1796fcc0e41f54054', 'Separar PF e PJ conta erro fatal', 'separar pf e pj conta erro fatal', '{"texto": "**Erro**: Mistura. Usa lucro pra mercado. Não sabe se deu lucro.\n**Regra**: 2 contas. PJ recebe, paga custo. Sobra = pró-labore dia 5.\n**Pró-labore**: 30% faturamento. Fatura R$ 5k = R$ 1.5k salário.\n**Heurística**: Se precisa pegar PJ pra pagar luz casa, preço errado.\n**Banco**: C6 PJ zero. Pix automático PF dia 5.\n**Resultado**: Sabe lucro real. Dívida PF não come PJ."}'::jsonb, 97, 535, 'LLAMA', 0.75, 'system', 0),
('32d2ee37c1db95f463727503693420127b6c68b1d2cc9564cc5e89ea017661f2', 'Vender todo dia script WhatsApp', 'vender todo dia script whatsapp', '{"texto": "**Status 8h**: `Cardápio hoje: Strogonoff R$ 18. 10 unidades. Reserva?`\n**Lista transmissão**: 256 contatos. Não grupo.\n**Script**: `Oi [nome], sobrou 2 marmitex. Quer pra almoço? Entrego 11h`.\n**Gatilho**: Escassez + urgência.\n**Heurística**: 100 msg = 10 venda = R$ 150 lucro/dia.\n**Bloqueio**: Se não responde 3x, tira lista. Não spamma.\n**Meta**: R$ 150/dia x 26 = R$ 3.9k/mês."}'::jsonb, 99, 545, 'LLAMA', 0.75, 'system', 0),
('d58f87074ddf38d2f1320a46e3df81ccbec24bcc866d425ab802391288e61607', 'Custo fixo cortar 50% negócio casa', 'custo fixo cortar 50 negocio casa', '{"texto": "**Lista**: Aluguel, luz, internet, celular, contador.\n**Corta**: Aluguel = casa. Luz = LED, desliga. Internet = 300MB basta. Celular = pré R$ 30. Contador = MEI não precisa.\n**Heurística**: Custo fixo < 20% faturamento. Fatura R$ 5k = máx R$ 1k fixo.\n**Negocia**: Fornecedor prazo 30 dias. Cliente à vista.\n**Economia**: R$ 1k/mês = R$ 12k/ano pra dívida."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('94cedeadb72c0522cc422f04848ac6c4b95c0ef9b2feb40c69349398f8c7fc44', 'Fundo emergência negócio 1 mês', 'fundo emergencia negocio 1 mes', '{"texto": "**Valor**: 1 mês custo fixo. Casa R$ 500, luz R$ 100, compra R$ 400 = R$ 1k.\n**Onde**: Conta PJ separada, Tesouro Selic.\n**Regra**: Só usa se 7 dias sem venda. Repõe 30 dias.\n**Heurística**: Sem fundo = pega empréstimo = dívida nova.\n**Constrói**: 10% lucro todo dia vai fundo. Vendeu R$ 200, R$ 20 guarda.\n**Meta**: 30 dias → 90 dias → 6 meses."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('7876727bd6a5debe10465b10e891b3e06ed2b849a03ab6b9671d288c4cd2fc62', 'Cliente fiado como cobrar sem perder', 'cliente fiado como cobrar sem perder', '{"texto": "**Antes**: Não vende fiado. `PIX na entrega`.\n**Já vendeu**: Script dia 1: `Oi, lembra R$ 50 marmitex? Pix hoje?`\nDia 3: `Preciso fechar caixa. Consegue hoje?`\nDia 7: `Vou precisar pausar até acertar. Pode?`\n**Heurística**: Vergonha é dele, não sua.\n**Corta**: 3x fiado = não vende mais. Lista negra.\n**Juros**: 2% a.m se amigo. Senão não."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('2ac67f5aa9409fc0b962a894d9c426e0313f0fdb90efa260fde0bc4abac74e44', 'Parceria dividir lucro dívida', 'parceria dividir lucro divida', '{"texto": "**Regra**: Parceiro entra com venda ou produção, não dinheiro.\n**Divide**: 50/50 lucro, não faturamento.\n**Contrato**: Simples, 1 página. Quem faz o quê, quem sai como.\n**Heurística**: Parceiro precisa mais que você. Senão rouba.\n**Evita**: Família, amigo. Mistura dá briga.\n**Teste**: 30 dias. Não deu = dissolve.\n**Meta**: Dobra venda, não divide trabalho."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('0b0b462e9b8e40de65e92a89b8128ef42118a0c8861ca471cb6caccb28fc5236', 'Precificação psicológica terminar 7 9', 'precificacao psicologica terminar 7 9', '{"texto": "**Heurística**: R$ 19,90 < R$ 20 cérebro. R$ 47 > R$ 50.\n**Produto**: R$ 10 custo. Marca R$ 29,90 não R$ 30.\n**Combo**: 3 por R$ 50. Unidade R$ 19,90. Cliente pega 3.\n**Ancoragem**: Mostra R$ 39 riscado, R$ 29,90. Parece desconto.\n**Teste A/B**: Semana R$ 27, semana R$ 29. Vê conversão.\n**Meta**: +15% lucro só preço."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('b0f0981d9580ccb8e2a70f1f0e415d3cea571e48f06e17ff455ce8ff0416ffa6', 'Plano B se negócio não der certo', 'plano b se negocio nao der certo', '{"texto": "**Gatilho**: 60 dias prejuízo ou < salário mínimo.\n**Plano B**: 1. Vira freela habilidade. 2. Uber 4h/noite R$ 2k/mês. 3. Faxina R$ 150/dia.\n**Não**: Empréstimo pra insistir.\n**Heurística**: Fecha rápido = perde pouco. Insiste = perde tudo.\n**Aprendizado**: Anota erro. Próximo negócio evita.\n**Dívida**: Negocia, não some. Nome sujo 5 anos."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('0dd304b8fd3ce3c5f088cded5006708b8132e1e7e21cfa04caae1c17f5b10407', 'Primeiro cliente achar hoje sem dinheiro', 'primeiro cliente achar hoje sem dinheiro', '{"texto": "**Lista**: 20 pessoas WhatsApp que te conhece.\n**Mensagem**: `Oi, tô começando [produto]. Faz pra família. Quer experimentar? Preço amigo R$ X. Se não gostar, não paga`.\n**Heurística**: 20 msg = 2 sim = R$ 40 hoje.\n**Foto**: Tira agora, luz janela.\n**Entrega**: Você mesmo, 2km raio.\n**Pede**: `Indica 1 amigo?` Indicação = 50% venda.\n**Meta**: 1 cliente/dia semana 1."}'::jsonb, 98, 540, 'LLAMA', 0.75, 'system', 0),
('29868e93ec4f15fa6849d2a65062650ac5f4ed2ba6a63898cad64bedf3b8116e', 'Postar venda Instagram legenda converte', 'postar venda instagram legenda converte', '{"texto": "**Foto**: Luz natural, fundo limpo, mão segurando.\n**Legenda AIDA**:\nAtenção: `Cansada de marmitex sem gosto?`\nInteresse: `Faço tempero vó, sem conservante.`\nDesejo: `Cliente falou: melhor que restaurante`.\nAção: `Cardápio hoje: comenta EU QUERO. 10 unidades`.\n**Story**: Enquete `Strogonoff ou Feijoada?` Resposta = lead.\n**Heurística**: Posta 11h ou 19h. 3x/semana."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('ea25d8ebddb28f27843f4a9eed89db7b9347f862794f26533a82585b0af1b4bb', 'Panfletagem dá resultado onde como', 'panfletagem da resultado onde como', '{"texto": "**Onde**: Porta escola 11h30, porta empresa 17h, feira domingo.\n**Panfleto**: A5, colorido, foto, preço grande, WhatsApp QR code.\n**Abordagem**: `Oi, licença rápida? Marmitex R$ 18 entrega. Cardápio?` Entrega, sai.\n**Heurística**: 1000 panfleto = 10 clientes = R$ 150 custo, R$ 1800/mês retorno.\n**Não**: Caixa correio, chão. Multa.\n**Parceiro**: Salão, academia deixa balcão."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('a7514bb76244c2f5df0770bae730cfa45c7359bab403b53144c7c5692b76c1e4', 'Feira livre ponto vender como consegue', 'feira livre ponto vender como consegue', '{"texto": "**Prefeitura**: Secretaria agricultura. Pede feirante. Taxa R$ 50/mês.\n**Teste**: Domingo, leva 20 unidades. Vende 15 = ponto bom.\n**Estrutura**: Mesa, toalha, placa preço grande, maquininha.\n**Heurística**: 6h-10h pico. Chega 5h pega lugar.\n**Produto**: Comida pronta, não precisa manipular. Bolo, pão, suco.\n**Lucro**: R$ 300/domingo x 4 = R$ 1.2k/mês."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('f446bb39b7affdf324fa714de5cd9ed2e508ab249c2e44cfafcd561eed60b5a0', 'iFood vale a pena taxa 27% conta', 'ifood vale a pena taxa 27 conta', '{"texto": "**Conta**: Vende R$ 30. iFood tira 27% = R$ 8,10. Embalagem R$ 2. Custo R$ 10. Sobra R$ 9,90.\n**Loja**: Mesmo R$ 30. Custo R$ 10. Sobra R$ 20.\n**Heurística**: iFood = marketing. Cliente novo, depois tira.\n**Estratégia**: Cardápio iFood R$ 35. Cardápio direto R$ 30. Cartão junto `Peça direto 10% off`.\n**Meta**: 30% iFood, 70% direto."}'::jsonb, 97, 535, 'LLAMA', 0.75, 'system', 0),
('baddab9d48d5d85abcb6288b3fcb2115f79376c070c9b345cebcea83b4622adb', 'Cliente recompra como fidelizar barato', 'cliente recompra como fidelizar barato', '{"texto": "**Cartão**: 10 compras = 1 grátis. Carimbo.\n**Aniversário**: Mensagem + cupom R$ 5.\n**Indicação**: Indica amigo = R$ 5 crédito pros 2.\n**Grupo VIP**: WhatsApp cliente ouro. Promoção 1h antes.\n**Heurística**: Custa 5x mais novo cliente. Fideliza.\n**Pós-venda**: `Chegou bem? Gostou?` 1h depois. Vira fã."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('2d963dca36b3f8de0f60b19951b5f52cc73b46f523a9747c992b3a1f5a1ab55e', 'Foto produto celular profissional', 'foto produto celular profissional', '{"texto": "**Luz**: Janela dia, não sol direto. 10h-15h.\n**Fundo**: Cartolina branca R$ 5. Ou madeira.\n**Ângulo**: 45° cima, não reto.\n**Edita**: Snapseed grátis. Brilho +10, contraste +5, saturação +10.\n**Heurística**: Foto boa vende 40% mais.\n**Não**: Flash, filtro exagerado, mão tremida.\n**Tripé**: R$ 20 Shopee."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('71aac13dc80f49d63059c9e36278ff44fa06859c4406d43780c506c3ee19ac75', 'Nome marca criar memorável', 'nome marca criar memoravel', '{"texto": "**Regra**: Curto 2 sílabas, som bom, sem ç/ã.\n`Bela Marmita` não. `Marmita Bela` sim.\n**Teste**: Fala barulho. Entende? Google existe?\n**Domínio**: .com.br R$ 40/ano. Instagram @nome livre.\n**Heurística**: Nome próprio + produto. `Ana Bolos`.\n**Registra**: INPI R$ 142 MEI. Protege 10 anos.\n**Evita**: Modinha, difícil falar."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('d6ea085322cd1b51d1fc893183a1c0e69c4652474c2520778a65a2a2e9980a74', 'Entrega grátis ou cobra como decide', 'entrega gratis ou cobra como decide', '{"texto": "**Conta**: Entrega 5km = R$ 5 gasolina + 30min tempo R$ 10 = R$ 15 custo.\n**Grátis**: Embute preço. Marmitex R$ 18 vira R$ 23.\n**Paga**: R$ 5 taxa. Cliente escolhe.\n**Heurística**: Raio 2km grátis, >2km cobra R$ 2/km.\n**Terceiriza**: Motoboy app R$ 8. Você foca produzir.\n**Meta**: Entrega < 15% preço."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('76d74d48b217bf55a5db084337ea8c7914e986553f88fbbfc69240e8e624574c', 'Reclamação cliente resposta script', 'reclamacao cliente resposta script', '{"texto": "**Script**: `Oi [nome], senti muito pelo ocorrido. Erro meu. Vou resolver agora: 1. Refaço grátis hoje. 2. Desconto 50% próxima. Qual prefere?`\n**Heurística**: Resposta <1h = 70% vira fã.\n**Não**: Discute, culpa, some.\n**Pede**: `Remove avaliação?` Após resolver.\n**Aprende**: Anota erro. Checklist evita repete.\n**Custo**: R$ 20 resolve. Processo R$ 2k."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('5b519f8f33342b0325681cb70e31781d552548417fdbe08035dbc73b8133fd12', 'Upsell aumenta ticket médio como', 'upsell aumenta ticket medio como', '{"texto": "**Momento**: Cliente decide, oferece.\n`Marmitex R$ 18. Por +R$ 5 leva suco e sobremesa`.\n**Heurística**: 30% aceita. Ticket R$ 18 vira R$ 23.\n**Custo**: Suco R$ 1, doce R$ 1. Lucro +R$ 3.\n**Combo**: `2 marmitex R$ 35` vs R$ 36. Leva 2.\n**Meta**: Ticket +20% = R$ 600/mês extra.\n**Treina**: Toda venda oferece 1."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('22aa1f0f72454dd2198ff9a704fd773386ec70cabfd47fa0f02f3c9d48c6d7cc', 'Sazonalidade produto vender ano todo', 'sazonalidade produto vender ano todo', '{"texto": "**Mapeia**: Jan dieta, Fev volta aula, Mar Páscoa, Mai mãe, Jun festa, Jul férias, Set criança, Out Halloween, Nov Black, Dez Natal.\n**Adapta**: Bolo pote → Ovo Páscoa → Festa Junina → Panetone.\n**Heurística**: 1 produto base + 4 sazonais.\n**Estoque**: Compra sazonal 30 dias antes, vende pico.\n**Meta**: Fatura estável 12 meses."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('54132fbe75f6345192c292df43cb5299c78752a7ff541ecc7b67120f98d3b5fe', 'Concorrente preço menor como competir', 'concorrente preco menor como competir', '{"texto": "**Não**: Briga preço. Morre junto.\n**Sim**: Valor. `Meu é R$ 20, dele R$ 15. Meu: entrega 30min, tempero caseiro, embala vácuo. Dele: 2h, congelado`.\n**Nich**: `Marmita fit`, `sem lactose`. Concorrente não faz.\n**Serviço**: Sorriso, bilhete, brinde.\n**Heurística**: Cliente troca por R$ 2, não por R$ 5 se ama.\n**Custo**: Calcula. <10% lucro = sai nicho."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('1a26725bd8a45d042e89e9e3b3f132d210d446730191bf03b7e2fe7c6c3b9773', 'Google Meu Negócio aparecer grátis', 'google meu negocio aparecer gratis', '{"texto": "**Cadastra**: google.com/business. Grátis.\n**Completa**: 100%. Foto, hora, telefone, site, cardápio.\n**Post**: 1x/semana. `Prato hoje`.\n**Avalia**: Pede cliente. 5 estrelas > 10 sobe busca.\n**Responde**: Toda avaliação, boa e ruim.\n**Heurística**: 70% cliente olha Google antes. 0 custo.\n**Verifica**: Cartão postal 15 dias."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('c48023359bcecc4ee373f7d3caf9fde4fd8fe6d114c860c20fbe4b2ba3b7cffe', 'WhatsApp Business catálogo configurar', 'whatsapp business catalogo configurar', '{"texto": "**Baixa**: WhatsApp Business grátis.\n**Catálogo**: 3 linhas > Foto > Nome > Preço > Descrição > Link.\n**Mensagem**: `Olá! Vi catálogo. Quero X`.\n**Resposta**: Automática `Obrigado! Respondo 1h`.\n**Etiqueta**: Novo, Pago, Entregue. Organiza.\n**Heurística**: Catálogo = loja 24h. +30% venda.\n**Lista**: Transmissão 256 contatos. Não grupo."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('c9f8823e3dc30985a2bb69af16fc6c530248f001d9505a57a4c8901417c1c657', 'Vídeo curto Reels vender produto', 'video curto reels vender produto', '{"texto": "**Roteiro 15s**: 0-3s Gancho `Cansado marmitex fria?` 3-10s Prova `Olha vapor` mostra. 10-15s CTA `Link bio`.\n**Luz**: Janela. **Áudio**: Microfone lapela R$ 20.\n**Texto**: Grande, 3 palavras.\n**Posta**: 12h e 19h.\n**Heurística**: 100 views = 1 venda. 1k views = R$ 200.\n**Não**: Dublagem, dancinha. Produto."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('26a501ca1006f6a5db8724831f991ac525604b1abda3335babe3c93b3bd54f08', 'Parceria loja vender consignado', 'parceria loja vender consignado', '{"texto": "**Proposta**: `Deixo 10 bolos, vende R$ 15, me paga R$ 10. Não vende, busco`.\n**Contrato**: Simples. 30 dias acerto.\n**Heurística**: Loja fluxo = você vende sem estar.\n**Margem**: 30% loja, 70% você.\n**Controle**: Planilha. Visita 2x/semana repõe.\n**Risco**: Calote. Começa 5 unidade.\n**Meta**: 10 loja x 10/dia = 100/dia."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('a735abdc687b6584b5c595c258cb97bb85881c97b0c363cdf31cb0177d8a8b7c', 'Feira evento vender quanto leva', 'feira evento vender quanto leva', '{"texto": "**Conta**: Público 5k. 1% compra = 50. Ticket R$ 20 = R$ 1k.\n**Custo**: Stand R$ 200 + produto R$ 300 + você R$ 200 = R$ 700. Lucro R$ 300.\n**Leva**: 2x venda esperada. Sobra volta.\n**Heurística**: < 3x custo stand = não vai.\n**Paga**: Cartão, pix. Dinheiro pouco.\n**Amostra**: Grátis. Cheiro vende."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('9226e6eaab05e225417550384e37d26453ebfc59aab3e415071c67ed7e2f8874', 'Indicação cliente pedir sem vergonha', 'indicacao cliente pedir sem vergonha', '{"texto": "**Momento**: Entrega, cliente feliz.\n**Script**: `Que bom gostou! Me ajuda? Se indicar amigo, você ganha R$ 5 crédito, ele ganha também`.\n**Cartão**: 2 lados. Frente você, verso `Indiquei: ___`.\n**Heurística**: Cliente indica 2,5x. Custa R$ 10, ganha R$ 40.\n**Não**: Implora. Troca valor.\n**Pede**: Google avaliação. Print QR code."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('64daab3d27c45376a808f8d3eb206c0002660e51b2b9a981667e883707bfa0a7', 'Sazonalidade preço aumentar quando', 'sazonalidade preco aumentar quando', '{"texto": "**Natal**: +20% nov-dez. Cliente aceita.\n**Inverno**: +15% sopa, fondue.\n**Verão**: -10% promoção, gira.\n**Heurística**: Aumenta 5% todo 6 meses. Inflação 5%.\n**Avisa**: `Reajuste anual` 30 dias antes. Não desculpa.\n**Testa**: Sobe R$ 1. Venda cai >20% = volta.\n**Cardápio**: Tira R$, põe só número. Dor -50%."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('4055610ce8c6aee36cc4e4ac556605e553c50da0cfb2eedda6647070f1220aaa', 'Estoque mínimo não perder venda', 'estoque minimo nao perder venda', '{"texto": "**Fórmula**: Venda dia média x dias reposição x 1.5.\nVende 20/dia. Repõe 3 dias. 20x3x1.5 = 90 estoque.\n**Planilha**: Produto | Estoque | Venda dia | Dias dura | Comprar\n**Alerta**: <7 dias = compra.\n**Heurística**: Ruptura = cliente vai concorrente.\n**Dinheiro**: Estoque = dinheiro parado. Gira 30 dias máx.\n**Perecível**: Compra 3 dias só."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('3b0de5277c2debbdbf10b3658af1d7254806138629bd222541b51f4007eb3cb2', 'Embalagem barata profissional', 'embalagem barata profissional', '{"texto": "**Marmita**: Pote 500ml R$ 0,80. Etiqueta R$ 0,20.\n**Adesivo**: `Feito com amor por [nome]` R$ 0,10.\n**Sacola**: Kraft R$ 0,50.\n**Total**: R$ 1,60. Agrega R$ 3 valor.\n**Heurística**: Cliente come com olho. Embalagem = 30% decisão.\n**Compra**: MercadoLivre 100 un. Shopee.\n**Não**: Jornal, saco lixo. Perde cliente."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('37ef2690dc403da445cfb05d5df4be708ca23b938736d5b63f1a4f83021ff350', 'Notion vs Obsidian vs Evernote qual vale', 'notion vs obsidian vs evernote qual vale', '{"texto": "**Notion**: R$ 50/mês. Tudo-em-um. Banco dados, wiki, tarefa. Lento 10k+ blocos.\n**Obsidian**: R$ 0 local. Markdown, grafo, plugin. Curva alta. Sync R$ 50/mês.\n**Evernote**: R$ 70/mês. Nota web clipper. Morto.\n**Heurística**: Solo criador = Obsidian. Time <10 = Notion. Corporativo legado = Evernote.\n**TCO**: Notion 3 anos R$ 1.800. Obsidian R$ 0.\n**Migração**: 200h se 5k notas. Custo trava.\n**Teste**: 14 dias free todos."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
('d7f86df7ff7f0e3cf464924843794528b37541bfffee6e0999b71a402d97c494', 'Canva Pro vs Adobe Express vs Figma', 'canva pro vs adobe express vs figma', '{"texto": "**Canva Pro**: R$ 289/ano. Template pronto, social media. Não-profissional print.\n**Adobe Express**: R$ 120/ano. Integra Photoshop. Limitado.\n**Figma**: R$ 0 free. R$ 75/mês Pro. UI/UX, dev handoff. Não é pra post.\n**Heurística**: Social media diário = Canva. Designer pro = Figma + Adobe.\n**ROI**: 1 post/dia. Canva economiza 2h = R$ 100/h = R$ 4k/mês.\n**Alternativa**: Photopea grátis = Photoshop web."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('029b23e886a0d9f6b2227edaef5e139636cc8dc273f129932b47bbb33a061dba', 'Zoom vs Google Meet vs Teams limite grátis', 'zoom vs google meet vs teams limite gratis', '{"texto": "**Zoom Free**: 40min, 100 pessoas. Grava local.\n**Meet Free**: 60min, 100 pessoas. Grava só Workspace.\n**Teams Free**: 60min, 100 pessoas. Grava não.\n**Heurística**: Reunião 1-1 = qualquer. >40min = Meet/Teams. Webinar = Zoom $150/mês.\n**Custo**: Zoom Pro R$ 75/mês. Meet R$ 35 Workspace.\n**Hack**: 40min Zoom, todos saem, entra link novo. Reset timer."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('e483035dd9d91050ef569b4040029723ffd6f4072ac7a5c7ae09cec217919d97', 'LastPass vs 1Password vs Bitwarden segurança', 'lastpass vs 1password vs bitwarden seguranca', '{"texto": "**Bitwarden**: R$ 0 pessoal, R$ 20/ano família. Open source, auditado. Self-host.\n**1Password**: R$ 180/ano. UX melhor, travel mode.\n**LastPass**: R$ 180/ano. Vazou 2022. Evita.\n**Heurística**: Senha vazada dark web = R$ 5k prejuízo médio.\n**ROI**: R$ 20/ano vs R$ 5k. 25000%.\n**Importa**: CSV todos. Migra 10min.\n**2FA**: Authy grátis. Não SMS."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('df1b184a739a8f392f717c89ef4857a516419d72a81c00840ec1eb37c5d817f3', 'Trello vs Asana vs ClickUp vs Monday', 'trello vs asana vs clickup vs monday', '{"texto": "**Trello**: R$ 25/user. Kanban simples. 10 quadro free.\n**Asana**: R$ 55/user. Timeline, workload. Complexo.\n**ClickUp**: R$ 35/user. Tudo-em-um. Lento.\n**Monday**: R$ 45/user. CRM junto. Bonito, caro.\n**Heurística**: <5 pessoas = Trello free. 5-20 = ClickUp. >20 = Asana.\n**TCO 10 users**: Trello R$ 3k/ano. Asana R$ 6.6k.\n**Migração**: 40h. Escolhe certo."}'::jsonb, 95, 525, 'LLAMA', 0.75, 'system', 0),
('9eb529df7f9e81bf71164bc13c0acb9d733986fb24cd934ab9c36550631af4b7', 'Grammarly vs LanguageTool português vale', 'grammarly vs languagetool portugues vale', '{"texto": "**Grammarly**: R$ 720/ano. Inglês 95%. PT 60%.\n**LanguageTool**: R$ 240/ano. PT 90%, EN 85%.\n**Word**: Grátis. PT 70%.\n**Heurística**: Escreve PT = LanguageTool. EN = Grammarly.\n**ROI**: 1h revisão/dia = 250h/ano. R$ 50/h = R$ 12.5k. Ferramenta R$ 240 = 52x.\n**Free**: LanguageTool 20k caracteres/mês. Suficiente."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('5cf4f44619b1d8e4b80b9737b0b6ba8254e8b54c8387648fc7dfc8984df965b9', 'Calendly vs Google Agenda agendamento', 'calendly vs google agenda agendamento', '{"texto": "**Calendly**: R$ 120/ano. Link público, buffer, lembrete, pagamento.\n**Google Agenda**: R$ 0. Agenda slot. Manual.\n**Heurística**: >5 agendamentos/semana = Calendly. ROI tempo.\n**Tempo**: 10min email vs 30s link. 9.5min x 20 = 3h/mês = R$ 300.\n**Alternativa**: Cal.com open source, self-host R$ 0.\n**Integra**: Zapier + Stripe cobra no agendamento."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('4919ede8cc70bb12efd4fa7acfcf87c6500a1b85981215aadd7a5f01813d1ca4', 'DocuSign vs Clicksign vs ZapSign', 'docusign vs clicksign vs zapsign', '{"texto": "**DocuSign**: R$ 120/mês. Marca global. Jurídico forte.\n**Clicksign**: R$ 60/mês. BR, ICP-Brasil. Suporte PT.\n**ZapSign**: R$ 40/mês. WhatsApp. Simples.\n**Heurística**: Contrato >R$ 10k = DocuSign. MEI = ZapSign.\n**Validade**: Todos MP 2.200-2. Art. 10. Mesma.\n**Volume**: 100 docs/mês. DocuSign R$ 1.2/doc. ZapSign R$ 0.4.\n**Free**: 5 docs/mês todos."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('185f207c4277eecc863f852bdf9fd75e3bf5e89879c545bf3178a2e8716b94f9', 'Slack vs Discord vs Teams comunicação time', 'slack vs discord vs teams comunicacao time', '{"texto": "**Slack**: R$ 40/user. 10k msg histórico free. Integra 2000 app.\n**Discord**: R$ 0. Canais voz 24h. Nicho gamer, dev.\n**Teams**: R$ 0 com M365. Vídeo junto.\n**Heurística**: Startup tech = Discord. Corp = Teams. Agência = Slack.\n**TCO 20 users**: Slack R$ 9.6k/ano. Discord R$ 0. Teams R$ 0 se já tem M365.\n**Migração**: 80h. Dói."}'::jsonb, 94, 520, 'LLAMA', 0.75, 'system', 0),
('230b140b2791b5bf76bf0c4250f15dea5efec2a6dfa1624440d19e2024ca9792', 'Loom vs Vidyard vs OBS gravar tela', 'loom vs vidyard vs obs gravar tela', '{"texto": "**Loom**: R$ 96/ano. 5min vídeo, link, analytics. 25 vídeo free.\n**Vidyard**: R$ 180/ano. CRM, CTA. Vendas.\n**OBS**: R$ 0. Local, ilimitado. Curva.\n**Heurística**: Suporte cliente = Loom. Vendas = Vidyard. Curso = OBS.\n**ROI**: 1 vídeo explica = -10 reunião. 1h = R$ 100.\n**Tempo**: Loom 2min. OBS 10min setup."}'::jsonb, 91, 505, 'LLAMA', 0.75, 'system', 0),
('4d6be8a17ed4aaecb054b66e4e4020a36cedd290f370efbaef51e6db4538d850', 'Zapier vs Make vs n8n automação', 'zapier vs make vs n8n automacao', '{"texto": "**Zapier**: R$ 240/ano 750 tarefas. Fácil, caro.\n**Make**: R$ 120/ano 10k ops. Visual, potente.\n**n8n**: R$ 0 self-host. Ilimitado. Técnico.\n**Heurística**: Não-dev = Zapier. Dev = n8n. Meio = Make.\n**Custo**: 10k tarefas/mês. Zapier R$ 1.200. Make R$ 120. n8n R$ 30 servidor.\n**Ex**: Salva R$ 1k/mês manual."}'::jsonb, 93, 515, 'LLAMA', 0.75, 'system', 0),
('2d1c76589b95f256b789dc8dc9594d0a1114fa98d5d749a44860df6e0198761d', 'Typeform vs Google Forms vs Tally', 'typeform vs google forms vs tally', '{"texto": "**Typeform**: R$ 300/ano. Bonito, 1 pergunta tela. Conversão 40%.\n**Tally**: R$ 0. 99% Typeform. Ilimitado.\n**Google Forms**: R$ 0. Feio, 10% conversão.\n**Heurística**: Lead caro >R$ 50 = Typeform/Tally. Pesquisa interna = Google.\n**ROI**: 1000 lead. Typeform 400 vs Google 100. Lead R$ 10 = R$ 3k dif.\n**Integra**: Zapier todos."}'::jsonb, 90, 500, 'LLAMA', 0.75, 'system', 0),
('eee0771cf233ee3669d0880126374acf71296afc3effc3b13cc7aa70b955334c', 'Airtable vs Notion database vs Excel', 'airtable vs notion database vs excel', '{"texto": "**Airtable**: R$ 120/ano. Banco relacional, API. CRM leve.\n**Notion DB**: R$ 50/ano. Wiki junto. Lento 10k row.\n**Excel**: R$ 0 ou R$ 38 M365. Poderoso, feio, solo.\n**Heurística**: <1k row = Notion. 1k-50k = Airtable. >50k = Supabase.\n**Migra**: Excel → Airtable 2h. 10k linha.\n**Limite**: Airtable 50k row plano R$ 120."}'::jsonb, 92, 510, 'LLAMA', 0.75, 'system', 0),
('1b1265539fe25aa67e547dfdaed2f8795aa90f53ae264574835cc2b15b211352', 'VPN Nord vs Express vs Proton custo', 'vpn nord vs express vs proton custo', '{"texto": "**Nord**: R$ 180/2 anos. 6000 server. Rápido.\n**Express**: R$ 500/2 anos. Melhor China. Caro.\n**Proton**: R$ 240/2 anos. Suíça, privacy. Free 1 país.\n**Heurística**: Torrent = Nord. China = Express. Privacidade = Proton. Custo = Nord.\n**Não precisa**: Banco. HTTPS já criptografa.\n**Risco**: VPN grátis vende dado.\n**Velocidade**: -10% todas."}'::jsonb, 89, 495, 'LLAMA', 0.75, 'system', 0),
('3fb27c89fc5a3beae2e9d861360bb8f61a14c65fd015192c25534f6929ac4cf5', 'AWS vs Google Cloud vs Azure para pequeno', 'aws vs google cloud vs azure para pequeno', '{"texto": "**AWS**: Maior, complexo. EC2 t3.micro free 1 ano. Depois R$ 50/mês.\n**GCP**: R$ 1.500 crédito. Cloud Run escala zero. R$ 0 se baixo.\n**Azure**: R$ 1.000 crédito. Integra M365.\n**Heurística**: Site WP = Hostinger R$ 15/mês. Não cloud.\n**SaaS**: GCP Cloud Run. 1M req/mês R$ 20.\n**Custo**: AWS 3x GCP baixo tráfego.\n**Aprende**: 40h cada."}'::jsonb, 96, 530, 'LLAMA', 0.75, 'system', 0),
